(window.STORIES=window.STORIES||[]).push(...[{"n": 46, "l": "الجزء الحادي عشر | لماذا اختار الله  العرب لرسالة الإسلام", "u": "https://www.facebook.com/groups/710210019782034/permalink/775879769881725/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الحادية_عشرة\n#رسالة_الإسلام_والعرب\nوقفنا المرة إللي فاتت عند رسول الله ﷺ لما أخذ أول خطوات الدعوة إلى الإسلام ،\nوبدأ يشوف مين هم الأشخاص المناسبين حوله عشان يقول لهم عن بعثته،\nوكان أول شخص أخبره رسول الله ﷺ هي زوجته خديجة رضي الله عنها إللي آمنت بيه بدون أي تردد\nوقلنا إنه دعا ثلاثة أشخاص كمان هم أبو بكر الصديق وعلي بن أبي طالب وزيد بن حارثة، وكل واحد فيهم له قصة مختلفة عن التاني\nقبل ما نعرف قصتهم في سؤال مهم لازم نعرف إجابته\nوهو: \nاشمعنى العرب بالذات إللي ربنا اختارهم عشان تكون فيهم الرسالة \nما هو أهل الأرض كلهم كانوا ضايعين زي ما شفنا المرة إللي فاتت ..يعني مكنش هتفرق كتير\n ليه مكنش رسول الله ﷺ من الروم أو من الفرس مثلا واشمعنى اللغة العربية بالذات إللي نزل بها القرآن\nتخيلوا إن مكة هي أنسب مكان يخرج منه نبي آخر الزمان، والوضع فيها مناسب جدا عشان تبدأ فيه الدعوة الإسلامية\nخلينا نأخذهم واحدة واحدة:\n◇أولا اختيار مكة بالذات:\n♡النقطة الأولى:\n مكة أو جزيرة العرب بصفة عامة مكنوش يعرفوا غير دين إبراهيم عليه السلام ،\nيعني بيعترفوا بوجود خالق للكون لكن حكموا معه غيره، فسهل إننا ندعي ناس تؤمن بالله لكن عندهم لخبطة من إننا ندعي ناس لا تؤمن بوجود إله اصلا ،أو بتقول إن الإله هو النار ولّا الفأر ولّا غيره\n فكأن ربنا بيعلمنا إننا في الدعوة نبدأ من الناس إللي هتستوعب الكلام أو هتتقبل فكرة الدين الأول وبعدين ندعي الناس إللي متعرفش حاجة خالص\nفندعي الأقرب فالأقرب..يعني منسبش أهلنا وجيرانا وأصحابنا من غير دعوة خالص ونروح ندعو غير المسلمين\nنشتغل على الدائرة القريبة مننا الأول ..ملقناش نتيجة يبقى نتجه لغيرهم\n♡النقطة الثانية \nالعرب مكنش عندهم تاريخ ثقافي يُذكر، حياة تعتبر بدائية بسيطة جدا،\nلكن الروم مثلا كان فيها فلسفات كثيرة وظهر فيهر فلاسفة زي أرِسطو وأفلاطون وغيرهم،\n والدولية الفارسية كان برده فيها ناس زي الفلاسفة كده كانوا بيحطوا شرائع للناس زي مَزدك ،\nوالهند كان فيها حكماء كثير جدا زي ما بيقولوا، \nومصر كانت أرض الفراعنة زمان ولهم تاريخهم الطويل وعندهم قوانين وتشريعات وكانوا تابعين للدولة الرومانية يعني كانوا نصارى،\nفتخيلوا لو كان رسول الله ﷺ ظهر وسط حضارة من الحضارات دي كان الناس هتقول إيه\nكانوا هيقولوا ده بيقلد الناس إللي سبقوه والكلام إللي بيقوله ده مجرد تطور للثقافات والمعتقدات السابقة\nتخيلوا إن ربنا لم يجعل رسول الله ﷺ يعرف يقول شعر زي باقي العرب مع إنه أبلغ العرب وأفصحهم،\nوالناس كلها عارفة ده عنه عشان لما القرآن ينزل ويبلغه لهم ميقولوش ده إنت إللي مؤلفه\n☆ مع إنهم هيقولوا برده زي ما هنشوف\nوالرسالة منزلتش في فلسطين مثلا عشان الناس متقولش إن رسول الله ﷺ أخذ من التوراة والإنجيل وحرّف فيهم وخلطهم ببعض؛ فراح مطلع الإسلام.\nومكة مكنش فيها لا يهود ولا نصارى إلا ورقة بن نوفل ومات\n☆واحنا شايفين في واقعنا أثر اختلاط أفكار المسلمين بأفكارالثقافات غير المسلمة \nمش بتشوفوا كثييير جدا من المسلمين بيحتفلوا بالكريسماس ولما نيجي نفهمهم بيقعدوا يعترضوا، وفيها إيه وعادي،\nشوفوا لبس البنات في الشوارع عامل إزاي هو مين اخترع موضة المقطع واللبس الضيق والمجسم و....و....ولما ننصح يقولوا احنا أحسن من غيرنا\nفنزول الرسالة في مكان شبه مُنعزل عن الأفكار الفلسفية والتشريعات المعقدة كان سبب في نقاء التكوين عند الصحابة،\nوعشان يحمي رسالة الإسلام من أي انحراف ويبقى ده دليل إن فعلا الدين ده من عند الله.\n☆زي بالضبط واحنا بنربي عيالنا\n الصح إننا نخليهم في شِبه عزلة كده أول سنين عمرهم عشان نشربهم الدين الصح،\nويبقوا راسخين فيه وبعدين ينطلقوا في المجتمع \nزي الصحابة بالضبط،\nكان المصدر الوحيد لهم هو القرآن عن طريق رسول الله ﷺ فعندنا المعلومات وعندنا القدوة \nوده أصل كل قواعد التربية...فاللي عايز يربي عياله صح يكون هو قدوة في الأول في عمل الصح ،\nومع القدوة تبدأ تديله المعلومات الصحيحة النقية بعيد عن أي تدخل من أحد\nمش الطفل يبقى أربع أو خمس سنين وأقل واحنا سايبنه قاعد عاليوتيوب طول اليوم يتفرج على ده وعلى ده ،\nويشوف ده ويشوف ده ويختلط مع ده إللي بيشتم ومع ده إللي بيكذب من غير أي رقابة\n◇عشان كلامي بس ميتفهمش غلط \nأنا بتكلم في عزلة نسبية تكونوا إنتم كأب وأب المصدر الرئيسي للمعلومات والتربية،\nيعني في قوانين بتحكم البيت في قواعد نمشي عليها مش أنا أقول كلمة وألاقي ألف واحد غيري يكسر كلمتي،\n زي فلانة ولا علانة... منخليش الكرتون والأفلام والمسلسلات هي إللي تربي العيال واحنا في الطراوة ومفيش أي توجيه ولا توضيح\nمش سايبين العيال للألعاب الإلكترونية طول اليوم تربي عندهم العنف وتدمر حواسهم،\nحافظوا على نقاء عيالكم إنتم بتأخذوهم صفحة بيضاء وإنتم إللي بتملوها وهتتحاسبوا عليها \n♡النقطة الثالثة:\nمكة ملهاش أي تاريخ عسكري ..معندهمش جيوش منظمة ..الأسلحة بتاعتهم قديمة..الخطط الحربية خطط بدائية \nمجرد قبائل متفرقة بيتهجموا على بعض وخلاص، ميعرفوش غير حرب الإغارات والسطو\n☆ياريت لو تحاولوا تربطوا بين وضع العرب قبل الإسلام وتشوفوا وضع العرب دلوقتي\nفلما بلد ملهاش أي تاريخ عسكري بالمنظر ده ولا عندهم أي قادة أمال مين الناس إللي هتفتح دولة فارس إللي عدد جيشها اثنين مليون جندي ...الناس دي كانت فين \nكانت موجودة لكن مكنش لها أي ذِكر غير بعد الإسلام،\nيعني الإسلام هو إللي هيغيرهم \nفكأن ربنا بيقول لنا عن طريق التجربة العملية إن العرب بدون إسلام ولا شيء\nالعرب جِنس لا يُصلحه إلا الإلتزام بالدين، ودي حاجة خاصة بالعرب بالذات،\nممكن غير العرب يكون كافر وفاجر ومع ذلك تلاقيه يشتغل ويُنتج ويبقى عنده تقدم علمي،\nزي أعظم دول في العالم في عهد رسول الله ﷺ فارس والروم وزي أمريكا والدول المتقدمة دلوقتي\nكان فين العرب زمان وهم كانوا كفار وبيعبدوا الأصنام مع إنهم كانوا بيؤمنوا بتوحيد الربوبية،\n يعني الكون له خالق وكان عندهم الكعبة وبيعظموها ، قصاد دولة فارس إللي مكنتش بتعترف إن في إله أصلا وبيقولوا إن النار هي آلهتهم وإن الأكاسرة دمهم فيه دم إلهي\nالعرب ساعتها مكنش لهم قيمة مع إن المفروض إن عندهم دين أكثر من غيرهم،\n لكن مع ذلك كانوا أذل الأمم ...ملهمش أي قيمة، لكن بعد الإسلام هنشوف إزاي إن الناس إللي مكنش لهم قيمة،\nلدرجة إن بلاد فارس كانوا بيتصدقوا على العرب بالقمح لما يحصل عندهم مجاعات؛\nهزموا جيوش فارس إللي كانت أعدادهم كبيرة جدا بالنسبة لأعداد المسلمين القليلة\nأنا عايزاكم تقارنوا وضع العرب قبل الإسلام  قصاد وضع دولة فارس ، ووضع العرب دلوقتي قصاد وضع الدول المتقدمة،\nالتشابه كبير جدا صح \nفهي رسالة لنا على مر التاريخ بتقول لنا طول ما العرب بعيد عن دينهم الإسلام هيكونوا متفرقين مذلولين ليس لهم أي قيمة.. متأخرين في كل المجالات،\nلكن لو تمسكوا بدينهم صح هيكونوا أعز البشر وهيتفوقوا على أي أحد غيرهم في كل المجالات؛ لأن ربنا ساعتها هيكون ناصر لهم ومعين\n☆فاكرين إن تنصروا الله ينصركم\n فالجيل إللي هيحمل رسالة الإسلام لازم يكون فاهم كويس أوي إن النصر بيد الله مهما كان العدو قوي طول ما الإنسان بينصر الله بتطبيق شرعه ربنا هينصره.\n◇ثانيا العرب نفسهم:\nالعرب في الجاهلية كان عندهم صفات تميزوا بها عن غيرهم والصفات دي مهمة ولازم تكون في الشخص إللي هيدافع عن رسالة الإسلام وفي كل داعية\nأول حاجة الصدق، الصدق كان عندهم حاجة أساسية، \nكانوا بيقرفوا من الكذب.. بيترفّعوا إنهم يكذبوا، \nميقدروش يكذبوا وإلا كان الناس تعايرهم \nفدي كانت طبيعة فيهم مش صفة اكتسبوها.. لأ..دي طبيعتهم إنهم مكنوش بيكذبوا\nفكان لازم الصفة دي تكون موجودة في الناس إللي هتنشر رسالة الإسلام تخيلوا لو كانوا قوم كذابين ..كانوا هيعملوا زي اليهود والنصارى ويحرفوا الدين\nحتى ربنا بيقول:\n\"  وَإِنَّ مِنْهُمْ لَفَرِيقًا يَلْوُونَ أَلْسِنَتَهُم بِالْكِتَابِ لِتَحْسَبُوهُ مِنَ الْكِتَابِ وَمَا هُوَ مِنَ الْكِتَابِ وَيَقُولُونَ هُوَ مِنْ عِندِ اللَّهِ وَمَا هُوَ مِنْ عِندِ اللَّهِ \"\nفالأمم لا تقوم إلا على أكتاف الصادقين\nمن الصفات برده كانت:  صفة الكرم ، \nالعرب كانوا كرماء جدا لدرجة إن الواحد فيهم كان ممكن يصرف أمواله كلها أو يذبح آخر شاة عنده وهي كل ما يملك عشان يكرم ضيفه\nوالصفة دي مهمة لأن الإسلام فيه الجهاد بالمال ، يعني هنلاقي إللي بيصرف كل أمواله في سبيل نشر الدين وتجهيز الجيوش\nوصفة كمان هي صفة الشجاعة ، \nوكان العرب بيفتخروا بالموت قتلا، مكنش عندهم أي مانع إن الواحد فيهم يموت في مقابل إنه يوفّي بكلمته أو يدافع عن صديقه\nمفيش جبان يقدر ينصر الدين،\nهتلاقيه خايف على نفسه من القتل وهتلاقيه خايف على أكل عيشه وخايف ..وخايف..\nهو ممكن يقتنع بإنه ينفق من ماله، لكن يبذل روحه دي ميقدرش،\nفتلاقيه عايش في ذل وهوان مقابل إنه يحافظ على حياته\nلكن العرب في الجاهلية كانت شجاعتهم فطرية زي الصدق كده واحنا هنشوف أمثلة على الشجاعة دي بعدين\nمن الصفات إللي تميزوا بها إنهم بيرفضوا يعيشوا في ذل،\nيعني هو عنده عنده يموت عزيز ولا إنه يعيش ذليل،\nولهم أشعار كثيرة جدا في الموضوع ده زي عنترة بن شداد لما كان بيقول في شعر له،\nإنه مش عايز يعيش خالد في الدنيا وهو ذليل لكن عادي جدا عنده إنه يموت مادام هيموت عزيز، \nوخدوا بالكم إنهم مكنوش بيؤمنوا بالآخرة \nيعني عندهم إللي بيموت ده كده خلاص انتهى\nفالمفروض إنهم يكونوا حريصين على الحياة أكثر من كده ومع ذلك كانوا شجعان جدا ومش بيهمهم المخاطر \nوكمان كانوا بيتميزوا بالصبر وقوة التحمل بسبب البيئة إللي كانوا بيعيشوا فيها، \nفهم كانوا أبعد الناس عن الترف، فلازم عشان يكون الإنسان ناجح يكون عنده قوة تحمل\n☆عايز أقول لكم قارنوا كده بين صفات العرب قبل الإسلام وبين صفات العرب دلوقتي بس مش قادرة عشان عارفة إن مفيش وجه مقارنة \nلأن للأسف حتى العرب دلوقتي مبقاش عندهم لا أخلاق الإسلام ولا أخلاق العرب في الجاهلية إلا القليل من الناس\n◇ثالثا: نزول القرآن باللغة العربية بالذات.\nنزول القرآن باللغة العربية كان بسبب إن أهل المكة بيتكلموا باللغة العربية،\nواحنا عارفين إن معجزة الأنبياء بتكون من نفس الحاجة إللي أهل البلد متميزين فيها ،\nفكان أهل مكة بارعين في اللغة العربية لدرجة إنهم وصلوا فيها لقمة الإعجاز البشري وخصوصا الشعر\nتلاقي واحد قال قصيدة يقوم التاني يرد عليه في نفس اللحظة...يبقى السيف على رقبته ويقول شعر \n☆إنت في إيه ولّا في إيه يابني\nفكان الشعر عندهم زي الكلام عندنا وهنشوف إزاي الشعر ده كان وسيلة مهمة جدا لنشر الإسلام\nفهو كان عامل زي وسائل الإعلام عندنا..القنوات الإخبارية كده\nده غير إن اللغة العربية هي أثْرَى اللغات، يعني لغة غنية بالمعاني والكلمات، \nكان العرب مجرد ما يسمعوا آيات القرآن فقط كانوا بيدخلوا في الإسلام، بعكس دلوقتي نيجي نسمع القرآن عادي مفيش تغيير \nلأن احنا مش فاهمين ..اتعودنا على الآيات وسماعها من غير ما نفهم ، \nعشان كده الجيل إللي هيقدر يُعيد بناء أمة الإسلام لازم يكون جيل مُتقن للغة العربية ،لا يقدم أي لغة على اللغة العربية\nوإحنا شايفين للأسف دلوقتي الناس لازم تدخل في كلامها كلمات أجنبية \nالفستان بقى اسمه دريس.. لا ويجمعوه بدريسات \nوبدل ما نعلم عيالنا اللغة العربية نكلمهم بلغات تانية روح يا حبيبي إلعب في 《الليفنج》 طب ما تقولي روح العب في الصالة،\nطيب كلمة اللّيفنج أصلا معناها غرفة معيشة ..تقدري تقولي روح يا حبيبي العب في غرفة المعيشة\nلا ويكتبوها بالعربي كمان طب حتى اكتبوا الحروف بالإنجليزي عشان نفهم أصلا الكلمة دي إيه إللي محصلتش \nلا عربي ولا انجليزي أصلا \nوكله كوم وإللي بيكتبوا العربي بالحروف الإنجليزي دول كوم تاني خالص \nفضيّعنا اللغة العربية بإيدنا ومبقناش فاهمين حاجة وأول خطوة لضياع الدين هو ضياع اللغة العربية وضياع تعظيمها من قلوبنا\n☆ثواني عشان محدش يفهم كلامي غلط\n مش معنى كلامي إننا منتعلمش اللغات التانية \nلأ ...بنتعلمها عادي لكن لها وقتها\nهنشوف من الصحابة إللي اتعلم لغات وكان متقنها وكان يعتبر هو الوحيد إللي متقنها كده،\nومع ذلك مكنش بيقعد يتكلم بها ولا كان بيدخل في كلامه كلمات من لغات ثانية\nالمقصود من الموضوع هو الفصل..نتكلم اللغة العربية فقط ونتكلم اللغات التانية في وقت ما نحتاجها\nأنا عارف إني طولت في الإجابة على سؤال لماذا العرب بالذات، مع إني اختصرت كثير والله\nبس دي قاعدة أساسية انطلق منها الإسلام فلازم نعرفها،\nلأن احنا مش بنتعلم السيرة من باب إنها قصة نتسلى بها،\nاحنا بنتعلمها عشان نقدر على الأقل نبني نفسنا ونربي عيالنا \nعشان لو مش هنقدر نبني أمة كاملة  يبقى على الأقل شاركنا باللي نقدر عليه في البناء\nنرجع لمحمد رسول الله ﷺ \nدعا رسول الله ﷺ علي بن أبي طالب للإسلام وكان عمره عشر سنوات وعلي بن أبي طالب هو ابن عم رسول الله ﷺ إللي كان اسمه عبد مناف وكان لقبه أبو طالب،\nوسبب دعوته هو إن علي بن أبي طالب كان عايش مع رسول الله ﷺ في بيته ،\nوده كان بسبب إن أبو طالب كان رجل فقير زي ما قلنا قبل كده،\nفحصلت أزمة اقتصادية في مكة فرسول الله ﷺ راح لعمه العباس وقال له تعال نساعد أبو طالب في أزمته،\nوكل واحد فينا يأخذ واحد من أبنائه عنده في البيت يصرف عليه ويبقى خففنا عليه شوية،\nفراحوا لأبي طالب وأخذ رسول الله ﷺ علي، وأخذ العباس جعفر بن أبي طالب،\nفلما بُعث رسول الله ﷺ عرض الإسلام على علي بن أبي طالب وهو عمره عشر سنين فأسلم علي وكان أول من أسلم من الصبيان\nمتخيلين طفل عنده عشر سنوات يؤمن ..لأ والفكرة نفسها غريبة \nفكرة عرض الإسلام إللي هو لسه محدش يعرف عنه حاجة على طفل صغير\nهو مش وارد إن الطفل ده يروح يقول لأصحابه وأصحابه يقولوا لأهاليهم والموضوع ينتشر في مكة\nوعلي مكنش هيبقى غلطان لأنه طفل مش هيستوعب القضية الخطيرة دي \nلكن عليّ تربى على يد رسول الله ﷺ فشاف من أخلاقه إللي خلاه يحبه حب أكثر من حبه لأبيه،\nوكمان رسول الله ﷺ كان عنده قاعدة في بداية الدعوة وهي إنه يدعو الشخص إللي هو بيحبه ويثق فيه،\nوكمان الشخص ده بيبادل رسول الله ﷺ نفس الحب ونفس الثقة،\n بغض النظر الشخص ده كان امرأة زي خديجة ولّا كان طفل زي علي بن أبي طالب،\nولّا مَوْلى.. عبد مُحرر يعني زي زيد بن حارثة إللي هنعرف قصته المرة الجاية إن شاء الله\nالجزء الي بعده هنا\nhttps://www.facebook.com/groups/710210019782034/?ref=share"}, {"n": 47, "l": "الجزء الثاني عشر | إسلام زيد بن حارثه وابو بكر الصديق | والجزء الثالث عشر | الدعوه السريه", "u": "https://www.facebook.com/groups/710210019782034/permalink/776327619836940/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثانية_عشرة\n#إسلام_زيد_بن_حارثة\n#إسلام_أبو_بكر_الصديق\nكنا واقفين المرة إللي فاتت عند إسلام علي بن أبي طالب وعرفنا إزاي أسلم مع إن كان عمره عشر سنين وكان هو أول من أسلم من الصبيان،\nكان في شخص ثاني عايش مع رسول الله ﷺ في بيته، هو مولاه زيد بن حارثة أو كان في الوقت ده اسمه زيد بن محمد،\nالمَوْلى يعني شخص كان عبد وسيده حرره،\nخلّونا نرجع بالزمن كده قبل بعثة رسول الله ﷺ بسنين طويلة، لما كان زيد بن حارثة غلام صغير ،\nكانت أمه واخداه وخرجت معاه عشان يزوروا قومها،\nوهم في الطريق أغار عليهم ناس من قبيلة ثانية، يعني هجم عليهم ناس وأخذوا زيد من أمه عشان يبيعوه في سوق العبيد ويقبضوا ثمنه\nواحنا قلنا قبل كده إن العرب كانوا عايشين على الإغارة على بعض،\nأخذوا زيد وراحوا سوق العبيد وباعوه وقبضوا ثمنه\nطبعا متسألوش عن قلب أم انفطر قلبها على ابنها إللي اتخطف قصاد عينها،\nولا تسألوا عن مشاعر الأب لما عرف إن ابنه اتخطف وعارف إنه هيتباع، وهيبقى عبد بعد ما كان حر،\nوالعبيد بيتعاملوا أسوأ معاملة وبينضربوا وبيشتغلوا،\nفمجرد التخيل إن ابنه يحصل معاه كده أكيد كان حاجة صعبة على نفسه،\nوهو مسكتش ومستسلمش حاول يدور عليه في كل مكان بس مكنش لاقيه\nفي الوقت ده كان زيد بن حارثة اتباع في سوق عكاظ،\nوسوق عكاظ ده كان سوق مشهور في الجاهلية بيبيعوا فيه كل حاجة ومنها العبيد،\nفاشترى زيد بن حارثة واحد من أهل مكة اسمه\n《حكيم بن حِزام》\nوكان حكيم بن حزام ابن أخ خديجة زوجة محمد رسول الله ﷺ، فاستوهبت زيد من حكيم ابن حزام،\nيعني طلبت منه إنه يوهبها زيد،\nويقال إن حكيم بن حزام اشتراه من الشام وجاء به لمكة وطلبته منه خديجة فأعطاه لها كهدية على اعتبار إنها عمته،\nفخديجة لما أخذت زيد راحت لزوجها محمد بن عبد الله وأعطته زيد بن حارثة، فكان زيد بيخدم سيده الجديد محمد بن عبد الله، فأحبه حب شديد جدا،\nوشاف منه الصدق والكرم والمعاملة الطيبة وكل ده كان قبل البعثة بسنين،\nفي يوم من الأيام كان في رجل جاء للحج فشاف زيد بن حارثة فعرفه فهو كان من قبيلته،\nرجع الرجل من الحج وعلى طول راح لحارثة أبو زيد إللي كان بيدور عليه،\nوقال له إنه شاف ابنه زيد في مكة عند رجل اسمه محمد من قبيلة قريش،\n فأبوه فرح طبعا، أخيرا لقى ابنه فراح واخد أخوه وسافروا مكة وتحملوا مشقة السفر عشان يوصلوا لابنه،\nولما وصلوا لمكة قعدوا يدوروا فين محمد بن عبد الله ؟\nلما وصلوا له حكوا له قصتهم وإزاي إن ابنهم كان حر والناس سرقته منهم وباعوه،\nفقالوا له: احنا عايزين ابننا ..احنا هنشتريه منك عادي، بس متزودش علينا في السعر لدرجة إننا منعرفش نشتريه\nفقال لهم : طيب أنا عندي اقتراح تاني..احنا نجيبه ونخيّره، لو عايز يروح معاكم هسيبه يروح معاكم،\nلكن لو اختارني فأنا مش هسيب حد اختارني\nفقالوا : والله أنصفت وزِدت في الإنصاف\nفنادى على زيد وسأله : إنت تعرف مين الناس دي يا زيد؟\nفقال زيد: أيوة ده أبي وده عمي \nفقال له : \nطيب هم عايزين يأخذوك معاهم ترجع لأهلك وتبقى حر وتعيش حياتك..إيه رأيك؟\nفقال : والله لا أختار على محمد أحد\nفأبوه اتصدم\nإزاي تقبل بحياة العبودية والذل على إنك ترجع مع أبوك لأمك وأهلك\nفقال لهم: والله أنا شفت منه حاجة ..مش موجودة في غيره ..يعني أنا لو وسط أهلي مش هيعاملوني زي ما هو بيعاملني\nحاول أبوه وعمه يقنعوه يرجع معاهم مفيش فايدة \nوالكلام ده كان قبل البعثة بسنين، فلما شاف محمد بن عبد الله الموقف ده قام وسط الناس وكلها وقال:\nأنا أشهدكم جميعا إني قد أعتقت زيد بن حارثة وتبنيته ..يعني أنا حررته من العبودية  واتبنيته فهو ابني يرثني وأرثه\nفلما شاف حارثة إن ابنه بقى ابن لرجل من قبيلة قريش واطمن إنه عايش حياة كريمة ومبسوط رضي وتركه في مكة ورجع لقومه\nزيد بن حارثة أو هنقول زيد بن محمد زي ما اتعرف بين الناس ، وكل الناس كانت بتناديه زيد بن محمد عاش مع محمد بن عبد الله لحد ما جاء له الوحي،\nوبقى محمد رسول الله ﷺ، فدعاه رسول الله ﷺ للإسلام،\nوقال له إنه رسول من عند الله، ربنا أرسله عشان يأمر الناس بعبادته هو وحده،\nفزيد بن حارثة كان بيحب رسول الله ﷺ وكان بيثق فيه لدرجة إنه مرضيش يرجع لأهله، \nورسول الله ﷺ كان بيحبه هو كمان،،\nفكده بقى متوافر فيه نفس الشروط إللي كانت في خديجة وعلي إللي أسلموا \nفأسلم زيد بن محمد وآمن برسول الله ﷺ ،\nوكان عمره في الوقت ده حوالي أربعة وثلاثين عام\nخذوا بالكم إن الموضوع مش سهل...ده واحد هيغير دينه كله، هيسيب دين أبائه وأجداده..هيواجه مجتمع بحاله،\nمش عارف الناس إزاي هتتقبل فكرة الإسلام\nلكن هو بسبب حبه لرسول الله ﷺ ، \nوكمان تفكيره بعقله إن الرجل ده صادق وعمره ما شافه بيكذب ،\nفمفيش واحد هيسيب الكذب على الناس ويكذب على الله\nوشايف إنه طول عمره بيساعد الناس بدون مقابل ، فهل هييجي بعد ما عدى الأربعين من عمره يطلب مصلحة لنفسه\nوشاف إزاي الرجل ده كان عفيف وبعيد عن كل الفواحش والمعاصي خصوصا في فترة الشباب إللي تعتبر الفترة إللي الشباب بيعملوا ما بدا لهم فيها،\nفإزاي رجل زي كده هيلعب في عقيدة الناس ودينهم\nثم الرجل ده لو كان عايز ملك ولا يبقى سيد مكة، مكنش ييجي بدين جديد ، بالعكس ده كان سهل إنه يأخذ طريق أسهل وهو اللات والعزى زي باقي أهل قريش\nفاجتمع لزيد حبه لرسول الله ﷺ وكمان الكلام المقنع\n☆فزيد بن محمد بيعلمنا نقطة مهمة جدا وهي إننا نشغل عقلنا شوية، يعني إن مش بس نتبع الشخص ونسمع كلامه عشان بنحبه ، لأ...لازم كلامه يكون كلامه مقنع ومعاه أدلة \nلأن ممكن عشان انا بحب شخص معين زي مثلا أمي ..أبي ..زوجي..صاحبتي..أسمع كلامهم من غير ما يكون كلامهم مقنع وممكن يكون غلط\nفلازم مع الحب يكون في دليل وكلام مقنع\nفزيد بن حارثة آمن بقلبه وآمن بعقله، وإللي يؤمن بقلبه وعقله صعب أو خلونا نقول مستحيل حد يقدر يغير رأيه أو يزعزع إيمانه،\nلأن ساعتها الإيمان بيكون راسخ وبعيد عن أي شبهة،\nوهنشوف مع بعض إزاي ربنا كان بيكلم الكفار بطريقة عقلية،\nعشان يفكروا ويطلعوا هم الإجابة ويؤمنوا بعقولهم\nيبقى عندنا دلوقتي ثلاثة من الذين آمنوا برسول الله ﷺ  : خديجة بنت خويلد ، علي بن أبي طالب، زيد بن محمد.\nالرابع بقى ده حكايته حكاية \nفاكرين لما كان زيد بن عمرو بن نفيل قاعد عند الكعبة وحصل حوار بينه وبين أمية بن أبي الصّلت عن نبي آخر الزمان وكان في واحد قاعد قريب منهم سمع الحوار ده،\nوكان اسمه عبد الله بن عثمان\nوكان صغير في السن ساعتها فهو اتولد بعد عام الفيل بسنتين وستة أشهر،\n☆يعني أصغر من رسول الله ﷺ بسنتين ونص تقريبا\nومكنش بيعبد الأصنام زي قومه، فهو كان دائم التفكر في الكون ، وكان بيفكر بعقله ، \nإزاي حجارة لا تسمع ولا ترى هي تكون إله، فمكنش مقتنع بها أصلا ، فلم يسجد لصنم أبدا\n ¤فيذكر أهل التاريخ إنه بعد ما سمع الحوار إللي كان بينهم ده قال إنه كان أول مرة يسمع عن موضوع الأنبياء والحاجات دي\nفراح لورقة بن نوفل وكان مشهور بينهم إنه تنصر وكان عنده من علم أهل الكتاب، وكان على طول بينظر للسماء ويدعو،\nفحكى له عن الحوار إللي سمعه وحب يتأكد منه فقال له ورقة إن فعلا الزمن ده زمن نبي وإنه قرب يظهر،\nوعدت الأيام ولما كبر كان بيعمل في التجارة، \nفكان بيسافر للشام للتجارة، في مرة وهو مسافر شاف رؤيا،\nفكان في صومعة لراهب في المكان ده، يُقال إنه كان بحيرى إللي اتكلمنا عنه قبل كده،\nالمهم عبد الله بن عثمان راح للراهب ده وسأله عن الرؤيا إللي شافها لأنه عارف إن اهل الكتاب عندهم علم مش موجود عند أي احد تاني،\nفلما حكى له الرؤيا سأله إنت منين:\n قال له من مكة\nفقال إيه هو عملك ؟...قال له : بشتغل تاجر\nفقال له الراهب: \nلو صدقت رؤياك فهيخرج في بلدك نبي وإنت هتؤمن به وهتكون وزير له وهو حي وخليفة له بعد موته\n◇القصة دي \nفيها كلام هل هي صحيحة ولّا لأ، أنا قلتها بس من باب العلم بالشيء وإن الرؤيا دي هتتحقق زي ما هنشوف إن شاء الله\nوكان عبد الله بن عثمان صاحب محمد بن عبد الله بن عبد المطلب طول عمره، فكان عارف أخلاقه، \nوطبعا كان بيحبه لأنه كان شبهه، يعني هم الإثنين مكنوش بيعبدوا الأصنام، \nومكنوش بيشربوا الخمر، كانوا كرماء،\nوكان عبد الله بن عثمان من سادات مكة زي محمد بن عبد الله،\n☆زي بالضبط لما تلاقي حد شبهك ومتفق معاك في كل التصرفات، وخصوصا لو كنت بتعمل حاجات محدش تقريبا بيعملها فتحس إنك غريب،\nفلما تلاقي حد شبهك؛ بتحبه أكثر من غيره وتحس معاه بأُنس\nفكان بينهم هم الإثنين توافق كبير جدا وكانوا على طول مع بعض، وكان عبد الله رجل غني ،\nوكان عنده علم واسع بالأنساب ، يعني كان عارف ده ابن مين وده ابن مين في الحقيقة، \nفاكرين لما قلنا إن كان بيحصل اختلاط في الأنساب بسبب أنواع الزواج إللي كان داخل فيها زني\nأهه هو كان عارف أنساب الناس كلها، ومع ذلك عمره ما عاب أي أحد،\nعشان كده وعشان باقي أخلاقه كان محبوب جدا بين الناس،\nعدت الأيام وجاء وقت بعثة محمد رسول الله ﷺ \nبعد ما رسول الله ﷺ عرض الإسلام على الثلاثة إللي اتكلمنا عنهم من أهل بيته وآمنوا،\nكان أول واحد يدعوه رسول الله من خارج بيته هو عبد الله بن عثمان أو عبد الله بن أبي قحافة أو أبو بكر الصديق\nأول ما قال له رسول الله ﷺ :\nيا أبا بكر أنا رسول الله ..ربنا أرسلني عشان أدعو الناس لعبادته وترك عبادة الأصنام.\nفقال له أبو بكر : أنت رسول وأنا أؤمن بك \nآمن بدون ما يسأله عن اي تفاصيل ولا حتى أي حاجة ..أنا رسول ..أنت رسول\nماهو مش لسه هيعرفه النهاردة...ده طول عمرهم مع بعض وهم الإثنين فاهمين بعض كويس\nفكان أول من آمن الرجال الأحرار عبد الله بن عثمان إللي كنيته أبو بكر الصديق وكان عمره سبعة وثلاثين ونصف تقريبا \nأبو بكر الصديق بعد إسلامه مباشرة عمل حاجة غريبة أوي منه لنفسه كده من غير ما أي حد يطلب منه\nكان له أصحاب بيحبهم وبيحبوه وبيثق فيهم،\nراح لهم وقال لهم على رسالة الإسلام وقعد يدعوهم لحد ما أسلموا، \nيعني أصلا محدش طلب منه حاجة، مجرد ما عرف الصح تحرك على طول وكأن رسالة الإسلام دي بتاعته هو \nخلونا نشوف مين الناس إللي أسلمت على يد أبو بكر الصديق:\nالأول: 《عثمان بن عفان》كان ٢٨ سنة \n الثاني: 《الزبير بن العوام》كان عنده ١٥ سنة\nالثالث: 《سعد بن أبي وقاص》كان عنده ١٧ سنة\n الرابع: 《طلحة بن عبيد الله》كان عنده ١٦ سنة\nالخامس:《عبد الرحمن بن عوف》 كان عنده ٣٠ سنة\nمتخلين ثلاثة منهم كان سنهم سن المرحلة الثانوية في عصرنا دلوقتي\nشوفوا الشباب في السن ده حواليكم بيفكروا إزاي ولّا دماغهم في إيه \nالثلاثة شباب دول ميغيروش أكل ولا شرب دول غيروا دين \nالبنات والشباب لما بييجوا يلتزموا بيقولوا أهلنا والمجتمع وأصحابنا والظروف و..و...\nدول غيروا دينهم في لحظة من غير ما يبصوا لمجتمع ولا أهل ولا أي حاجة..أول ما عرفوا إن ده الحق خلاص اتبعوا فورا\nإنتم متخيلين الشباب الصغير ده هيواجه إيه...هم مفكروش في إللي أهل ممكة ممكن يعملوه فيهم؟\nمفكروش في أهلهم ..مفكروش في حياتهم إللي هتتقلب رأسا على عقب\nإزاي قدروا يأخذوا قرار زي ده في لحظة\nسبب بسيط جدا وهو إنهم عرفوا إن هو ده الحق فآمنوا بقلوبهم وبعقولهم، ومكنش عندهم اتباع الهوى \nعرف إن ده الحق خلاص مش هسيبه مهما حصل\nفهل نتعجب من الشباب دي ولّا نتعجب من أبو بكر إللي راح دعاهم، إنتم متخيلين إن الخمسة دول بأعمالهم كلها في ميزان حسنات أبي بكر الصديق\nتخيل إنك لو دعيت حد إنه يعمل حاجة صح ويعملها عمله هيكون في ميزان حسناتك\nوفي نفس الوقت لو دعيت حد إنه يتفرج على أغنية ولّا فيلم ولا شجعتِ صاحبتك إنها تحب شاب ولا شجعتيها على لبسها الغلط ولا...ولا... فهو في ميزان سيئاتك\nأبو بكر مقلش أنا مليش دعوة محدش قال لي ادعي الناس، فكان ممكن يكتفي إنه يؤمن وخلاص، \nلكن هو معملش كده راح وبدأ يدعو والغريب إن الخمسة دول من قبائل متفرقة وفيهم واحد هو ابن عمة رسول الله ﷺ \nإللي هو الزبير، كان ممكن يقول هو قريب رسول الله ﷺ فهو يدعوه، لأ ...مكنش بيفكر في كده..كان بيفكر إنه عايز يُدخل في الإسلام كل إللي يقدر عليه، \nكان بيسارع إنه يكون سبب في هداية الناس ، كان زي ما بيحب الخير لنفسه أحبه لأصحابه،\nكان حاسس إن الدين ده مسؤوليته وإنه لازم يوصله لكل واحد يقدر يوصله له\nوأبو بكر الصديق موقعش في خطأ بعض الدعاة في عصرنا ،\nبيدعوا الناس وسايبين أهل بيتهم بدون دعوة\nراح أبو بكر لبيته وكلم زوجته أم رومان ودعاها للإسلام فأسلمت وأسلم كل أبناء أبي بكر الصديق ما عدا ابنه الأكبر عبد الرحمن أسلم متأخر زي ما هنشوف بعدين،\nودعا عبد له اسمه 《عامر بن فُهيرة》 للإسلام فأسلم راح مُعتِقه\nإيه الحركة والنشاط دي والجهد لنشر الإسلام من أول يوم إسلامه دي\nأمال بعد كده هيعمل إيه\nثم إيه إللي خلى الناس دي تسمع كلامه كده على طول من غير حتى ما تروح تسأل رسول الله ﷺ وتتأكد هل الكلام إللي أبو بكر بيقوله ده صحيح ولّا لأ\nورسول الله ﷺ في الوقت ده عمل إيه ...و دعا مين تاني من الناس \nكل ده هنعرفه الجزء الجاي إن شاء الله\n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثالثة_عشرة\n#الدعوة_السرية\nكنا واقفين المرة إللي فاتت عند أبي بكر عبد الله بن أبي قحافة لما راح دعا خمسة من أصحابه للدين الجديد وكلهم أسلموا وكمان دعا أهل بيته فأسلموا همّ كمان،\nوكنا بنسأل لماذا استجاب الشباب لدعوة أبي بكر من غير حتى ما يروحوا يتأكدوا من محمد بن عبد الله إللي هو المفروض إنه صاحب الرسالة\nيجاوبنا على السؤال ده واحد من إللي أسلموا هو طلحة بن عبيد الله، وخلينا نركز كده مع كلام طلحة عشان نتعلم إزاي ندعو الناس عشان تستجيب لنا زي أبي بكر \nبيقول عن أبي بكر\n◇ أولا:\nكان لين الكلام يعني بيختار الكلمات الرقيقة وأسلوبه بسيط ومُقنع،\n◇ثانيا: \nكان تاجر صاحب أخلاق عالية واستقامة، كان بيكسب الناس من خلال تجارته بعكس طبيعة التجار تخسر الناس بسبب التجارة\nكان تاجر صادق كريم ورحيم بيرأف بأحوال الناس،\nكان بيعطيهم أكثر ما بيأخذ منهم وبيحسن لهم،\nوالقلوب ربنا طبعها على إنها تحب إللي يُحسن لها وتكره إللي بيسيء لها\n◇ثالثا:\nكان متميز في علم الأنساب ومع ذلك كان أي أحد يقعد معاه، والناس بتألفه بسرعة ويكلم أي أحد سواء الطبقة المثقفة وأشراف مكة،\nأو حتى الشباب الصغير والعبيد يعني كان متواضع لا يتكبر على أحد، \nوعمره ما طعن في نسب أحد من الناس مع إنه عارف النقائص إللي في أنساب كل واحد فيهم يعني من الآخر نقطة ضعفهم في إيده ومع ذلك لم يُعيّر أحد منهم أبدا\nتخيلوا أحد بالأخلاق دي إزاي الناس متحبهوش،\n فهو أصلا كان باني الثقة دي عند الناس من البداية \nالواحد يتوقع إن أبو بكر بعد مجهود أول يوم ده يريح بقى، ويقول أنا عملت إللي عليّ وزيادة \nلأ...هو معملش كده\nتاني يوم من إسلامه ودعوته للخمسة إللي قلنا عليهم ، راح  دعا أربعة غيرهم وأسلموا\n《أبو عبيدة عامر بن الجراح》\n《عثمان بن مظعون》\n《الأرقم بن أبي الأرقم》\n《أبو سلمة بن عبد الأسد》\nكل الناس دي أسلمت وصدقت أبي بكر لما كلمهم\nهو كان بيأخذهم لرسول الله ﷺ بعدين عشان يعرفهم أكثر على الإسلام،\nلكن هو إللي دعاهم من البداية مكنش مستني من رسول الله ﷺ إنه يقول له روح ادعي الناس،\nوخصوصا إن الإسلام كان لسه في البداية يعني مكنش فيه تحفيز على الدعوة ولا كان لسه رسول الله ﷺ قال إن إللي يدعي أحد هيبقى له نفس الأجر،\nبدون أي محفّزات وده كان نشاط أبي بكر \n☆لازم نقف هنا وقفة مع نفسنا\nأبو بكر الصديق جاء للإسلام بالناس دي في أول يومين من إسلامه ومكنش لسه في معلومات كثيرة ...احنا جئنا بمين؟\nهل علمنا أحد معلومة ولو بسيطة؟\nهل دعينا أهلنا وأصحابنا ومعارفنا ؟\nهل ساعدنا أحد إنه يتخلص من ذنب عايش عليه سنين؟\nهل علمنا الشباب الصغير التائه من هو الله؟\nهل حتى بنتحرك للدعوة إلى الله بنفس حماس أبي بكر؟\nهل احنا حاسين بالإنتماء للدين وإن هو قضيتنا وإني أنا المسؤوول عنه فأنصره وأنشره بكل قوتي؟\nولّا الإسلام على هامش حياتنا...والله الظروف سمحت كان بها، مسمحتش فأنا مش هقطع نفسي يعني \nأسئلة كثيرة محتاجة إننا نجاوب عليها بيننا وبين أنفسنا\nأعداد المسلمين بدأت تزيد واحدة واحدة..عندنا أهل بيت رسول الله ﷺ زوجته وبناته ومن يعيش معه في بيته،\nأهل بيت أبي بكر الصديق وتسعة من أصحابه، وكل واحد من التسعة دول بدأ يدعو إللي يعرفه ويحبه ويثق فيه،\nلحد ما وصل عدد الذين أسلموا إلى أربعين مسلم،\nمنهم سبعة وعشرين من الأغنياء وثلاثة عشر من الفقراء،\nيعني مكنش الإسلام ثورة من الفقراء على الأغنياء زي ما بعض الناس بتقول\nفزي ما شفنا... الإسلام لكل الفئات ..الصغير والكبير ،\nالحر والعبد ،الغني والفقير، الرجل والمرأة\nأي إنسان يقدر يدخل في الإسلام، بدون تفرقة عنصرية؛لأن المفاضلة في الإسلام مختلفة\nإزاي\nاحنا كلنا مختلفين عن بعض، فهنلاقي الذكي والأقل ذكاء ودي حاجة مش بإيدنا إننا نغيرها،\nوفي إللي بشرته بيضاء وإللي بشرته سمراء ودي برده حاجة مش بإيده يغيرها وهكذا\nفلأن الإسلام جاء بالعدل الكامل، فإزاي هيفاضل بين الناس على حاجة هم مش بإيدهم يغيروها\nعشان كده معيار المفاضلة بين الناس هيكون بحاجة كلنا نقدر نعملها، \nكلنا نقدر نكتسبها.. الصغير والكبير والغني والفقير والعربي وغير العربي وهي 《التقوى 》\nيعني فلان أفضل من فلان بسبب التقوى...فكل واحد يقدر يكون تقي\nفاللي عايز يتحول من إنه غير تقي ليكون تقي بكل بساطة هيتبع الدين\nوبرده الأخلاق الحسنة...إللي بيكذب وعايز يكون صادق يقدر إنه يكون صادق،\nفكل الحاجات دي مُكتسبة.. يقدر أي إنسان إنه يحصل عليها، وده من كمال عدل الله لأنه لا يحاسِب الناس على حاجة مستحيل يغيروها\nرسول الله ﷺ كان بيدعو الناس رجل رجل بيختار ناس معينة يكلمهم،\nوكان بيعلم الناس إللي يسلموا إنهم يعملوا كده،\n☆خلّوا الموضوع سر\nواستمر رسول الله ﷺ يدعو هو وأصحابه بين أهل مكة في السر لمدة ثلاث سنين\n◇ممكن حد يسأل ليه رسول الله ﷺ يقعد يدعوا الناس في السر ثلاث سنين،\nماهو كان ممكن يقوم في مكة من أول يوم ويدعو الناس للإسلام،\nوخصوصا إن دعوة الإسلام مُقنعة ومع شوية معجزات الناس هتقتنع وهتؤمن \n¤أولا:\nهنحط قاعدة كده عشان هتمشي معانا في السيرة كلها وهي إن رسول الله ﷺ《 رسول》 يعني بشر حامل رسالة ..بيوصل إللي ربنا بيقوله له، \nمش بيجيب أي حاجة من عنده ..كل خطوة بيعملها هي بأمر من عند ربنا\n¤ثانيا: \nمش كل حاجة مُقنعة وجميلة الناس هتتقبلها\nفهو عارف إن دعوة الإسلام مهما كانت مقنعة فهي هتواجه محاربة شديدة جدا،\nلو مش من عوام الناس فمن السادة إللي الدين هيوقف لهم مصالحهم \nفتخيلوا كده لو رسول الله ﷺ من أول يوم نزل عليه الوحي وقف وسط مكة وقبل ما يدعو أي أحد وقال يا جماعة أنا رسول الله وبدأ يشرح لهم الإسلام،\nوعارضه السادة وعملوا معاه مشاكل وبدأوا يؤذوه، ويشوّشوا على دعوته كان إيه إللي هيحصل\nإللي كان عنده نية إنه يسلم هيخاف ويرجع في كلامه،\nوإللي اقتنع وعايز يُسلم هيفكر ألف مرة قبل ما يسأل حتى، \nعشان ميتعرضش للأذى،\nوهتلاقوا ده بكلمة وده يقول كلمة وده يطلع شبهة وده يسأل سؤال،\nورسول الله ﷺ بشر مش هيعرف يرد على كل ده في وقت واحد وخصوصا إن في ناس هتجادل وتسخر منه،\nفكده هيضيع الحق وتضيع هيبة الرسالة \nوربنا قادر على فكرة إنه يحمي رسوله من كل أذى\nلكن ربنا بيضع لنا قواعد عشان نقدر نبني عليها في أي زمن لو تشابهت الظروف مع الظروف في عهد رسول الله ﷺ \n☆عارفين زي إيه\nزي لما تبقى البنت لسه ملتزمة جديد ولبست النقاب مثلا وراحت تزور أقاربها وكلهم متجمعين ، وده يقول كلمة وده يسخر وده يسأل سؤال،\nفالبنت هتلاقي نفسها ضايعة في النص وبتواجههم كلهم لوحدها لا عارفة ترد على ده ولا عارفة تشرح لده،\nوكمان هي نفسيا هتتأثر وعزيمتها تضعف وفي ناس بترجع عن طريق الإلتزام بسبب مواقف زي كده\nبعكس مثلا لو الأم أو الاب واقفين في صفها وبيدافعوا عنها،\nوالأب بيرد على إللي بيسخر، وأختها بتشرح للي بيسأل،\nوأخوها بيشجعها وبيقول لها ميهمكيش إنتِ صح\nأكيد الوضع والنتيجة هتبقى مختلفة\nفهو ده إللي عمله رسول الله ﷺ الأول، \nقبل ما يواجه الكل بدأ يجمع حواليه إللي يساعدوه ويقفوا معاه\nخدوا بالكم إن السيرة دي مش بنعرفها للتسلية \nده منهج، ربنا منزله لنا عشان نطبقه في حياتنا\nبيقول لنا لما تيجوا تدعوا اختاروا الأشخاص المناسبين،\nلما تيجوا تلتزموا متواجهوش أهلكم في البيت كلهم مرة واحدة،\nشوفوا مين في البيت إللي تحسوا إنكم تعرفوا تدعوه وكلموه وخذوه في صفكم،\nواعملوا كده مع واحد ورا الثاني، عشان لو حصلت مواجهة بالكلام تلاقي إللي يساعدك ويقف جنبك\n◇ثالثا:\nربنا بيقول لنا بالطريقة العملية إننا لما نكون عايزين نبني دولة وكانت ظروف حياتنا زي ظروف رسول الله ﷺ لما بدأ الدعوة يبقى نعمل زيه وندعو في السر،\nوكان حصل أيام الاتحاد السوفييتي زمان، إن المسلمين كانوا بيدعو في السر، لأن مجرد إن الواحد يشيل مصحف دي كانت جريمة يعاقب عليها القانون\nوإللي بيصلي كانوا بيعذبوه ويقتلوه\nفكان لازم يكون في سرية في الوقت ده عشان يحافظوا على استمرار الإسلام وإلا اختفى من المناطق دي تماما\n☆والاتحاد السوفييتي زمان إللي هو روسيا والمناطق المحيطة بها.\n◇وفي قاعدة مهمة جدا رسول الله ﷺ بيعلمها لنا وهي إن الداعية مطلوب منه إنه يحافظ على حياته وعلى نفسه من الموت،\nمش عشان هو خايف من الموت \nلأ..ده عشان يحافظ على الدين وعلى استمرار رسالة الإسلام،\nتخيلوا كده معايا لو كل العلماء قُتلوا ومتبقاش في الناس غير الجُهّال إللي بيضلوا الناس بفتاويهم الضالة،\nالناس هتكون مصيرها إيه\nهتعرف الدين الصحيح إزاي لو كل العلماء ماتوا في سبيل الله\nورسول الله ﷺ قال: \n\"إِنَّ اللَّهَ لَا يَقْبِضُ الْعِلْمَ انْتِزَاعًا يَنْتَزِعُهُ مِنْ الْعِبَادِ وَلَكِنْ يَقْبِضُ الْعِلْمَ بِقَبْضِ الْعُلَمَاءِ حَتَّى إِذَا لَمْ يُبْقِ عَالِمًا اتَّخَذَ النَّاسُ رُءُوسًا جُهَّالًا فَسُئِلُوا فَأَفْتَوْا بِغَيْرِ عِلْمٍ فَضَلُّوا وَأَضَلُّوا\"\nيعني ربنا مش بيأخذ العلم من قلوب العباد، لكن العلماء لما يموتوا مش هيبقى في حد يعلم الناس فالناس هتضل،\nويضيع الدين، فمن أسباب الحفاظ على الدين وجود العلماء إللي يعلموا الدين ده،\nلااااااكن مش معنى كده إن العالم يحرّف في الدين عشان يحافظ على حياته\nالإمام أحمد بن حنبل اتعرض للتعذيب الشديد عشان يحرف في الدين ويقول إن القرآن مخلوق،\n ومع ذلك كان صامد واتحمل التعذيب وكان مستعد للموت ولا إنه يحرّف في الدين وثبت على القول الصحيح وهو إن القرآن كلام الله غير مخلوق \nفالعالِم بيحافظ على حياته عشان يحافظ على الدين ، لكن لو عشان يحافظ على حياته يحرّف في الدين يبقى يموت أحسن\nعشان كده رسول الله ﷺ كان بيدعو الناس في السر لمدة ثلاث سنوات كاملة،\nعشان يحط قواعد تكون أساس له لما يواجه أهل مكة بعدين\nيعني رسول الله ﷺ مكنش جبان خدوا بالكم\nلأن الفرق بين الحكمة في الحفاظ على النفس عشان الرسالة تستمر وبين إن الإنسان بيعمل كده عشان هو جبان خطوة\nلو الشخص ده قاعد كده في بيته لا بيدعو ولا بيحاول يصلح ولا بيحاول يوصل الدين ولا يقول كلمة حق،\nيبقى ده كده جبان\nوده عكس إللي رسول الله ﷺ كان بيعمله،\nرسول الله ﷺ كان بيدعو في السر وينشر الإسلام بين الناس وفي نفس الوقت واخد بالأسباب عشان يحافظ على حياته\nرسول الله ﷺ كان بيدعو الناس للإسلام وبيعرفهم به كان بيقول لهم:\nإن الكون ده له إله واحد هو الخالق وهو الرازق والمحيي والمميت ليس له شريك، وهو أرسلني عشان أوضح لكم إزاي تعبدوه،\nإله الكون الله بيأمركم بالصلاة والزكاة والصيام وصلة الأرحام والصدق والعفاف،\nوفي أول سنة من البعثة كانت صلاة الليل فرض،\nيعني كانوا بيصلوا قيام الليل ركعتين قبل طلوع الشمس ،\nوكمان كانوا بيصلوا ركعتين قبل غروب الشمس،\n\" وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِ\"\nومن أول يوم من البعثة بعد فتور الوحي ونزول سورة المدثر ، نزلت أول آيات سورة المزمل عشان تأمر رسول الله ﷺ بالصلاة:\n\"يَا أَيُّهَا الْمُزَّمِّلُ. قُمِ اللَّيْلَ إِلاَّ قَلِيلا. نِصْفَهُ أَوِ انقُصْ مِنْهُ قَلِيلا. أَوْ زِدْ عَلَيْهِ وَرَتِّلِ الْقُرْآنَ تَرْتِيلا\"\nفكان أي أحد بيُسلم في السنة الأولى كان يجب عليه الصلاة،\nوهي كانت مختلفة عن الصلاة بتاعتنا دلوقتي ،\nلأن الصلاة إللي احنا عارفينها دلوقتي اتفرضت بعدين زي ما هنشوف إن شاء الله\nخلال أول ثلاث سنوات من البعثة أسلم حوالي ستون رجل وامرأة،\nوكان من إللي أسلموا: بلال بن رباح وسمية وزوجها ياسر وابنهما عمار،\nخلال الثلاث سنوات دول أهل مكة كانوا بيشوفوا رسول الله ﷺ وهو بيصلي، وكان أهل المسلمين إللي أسلموا بيشوفهم برده،\nلكن محدش كان بيعلق \nكانوا سايبينهم عادي ولو حد سأل كانوا بيشرحوا لهم الإسلام وخلاص،\nوالسبب في إن أهل مكة مكنوش بيتعرضوا للمسلمين دول ولا بيؤذوهم،\n إنهم كانوا مفكرين إن الناس دي متبعين نفس منهج ورقة بن نوفل، وزيد بن عمرو بن نفيل وأمية بن أبي الصلت،\nإللي احنا اتكلمنا عنهم قبل كده،\nميعرفوش إن رسالة الإسلام دي رسالة جديدة أصلها التوحيد أيوة لكن شرائعها مختلفة عن الشرائع السابقة \nفكانوا سايبينهم،\nكانوا ماشيين بمبدأ ما لقيصر لقيصر وما لله لله، يعني بالبلدي كده الدين لله والوطن للجميع\nمادام إنت بتعبد الإله بتاعك في بيتك ولّا في مسجدك خلاص اعبد براحتك\nيعني الدين ده في الجامع بس، تطلع من الجامع تسيب الدين وراك\nلكن تقولي دين يتدخل في كل صغيرة وكبيرة وتقولي إله واحد إللي يحكم وتقول حلال وحرام....لاااا هنا تقف بقى\nعشان كده مكنش في أي أحد بيعترض على المسلمين ولا على رسول الله ﷺ لما كانوا بيصلوا أو بيشرحوا الإسلام لأي أحد بيسأل هم بيعملوا إيه\nرسول الله ﷺ خلال الثلاث سنوات دي كان محتاج مكان يعلم فيه المسلمين الإسلام،\nلكن مينفعش يطلع يقعد وسط أهل مكة كده ويعلمهم،\nالمسلمين كده هيتعرفوا\nواحنا بنرتب إننا هنعلن الدعوة دي في يوم من الأيام، فلو أهل مكة عرفوا كل المسلمين ممكن يقتلوهم كلهم ويقضوا عليهم كلهم\nيبقى لازم نتعلم في الخفاء من غير ما أي أحد يعرف وكمان عشان يبقى ده المكان إللي هنجتمع فيه دائما،\nمين الشخص المناسب إللي يقدر يجتمع عنده المسلمون\nأبو بكر\nلا مش هينفع ده أول مكان هيتعرف وهيكون متراقب ،\nطيب بيت رسول الله ﷺ نفسه \nبرده مش هينفع، طيب مين الشخص المناسب \nاختار رسول الله ﷺ دار الأرقم بن أبي الأرقم إللي أسلم على يد أبي بكر الصديق\nاحنا لما نسمع إن رسول الله ﷺ اختار الأرقم للمهمة الخطيرة دي،\nييجي في دماغنا إن الأرقم ده رجل كبير قوي له مَنعة ويقدر يدافع عن نفسه وعن المسلمين لو أي أحد عرف إن بيته هو مقر اجتماع أتباع الدين الجديد صح\nطيب خذوا المفاجأة دي\nالأرقم بن أبي الأرقم لما أسلم ولما كان المسلمين بيجتمعوا في بيته كان عمره ثلاثة عشر سنة \n١٣ سنة...متخيلين\nيعني إللي في سنه عندنا دلوقتي في إعدادي\nإزاي طفل زي ده يكون بيته هو المقر الرئيسي لاجتماع المسلمين\nيعني هو مش ممكن لسانه يفلت بكلمة هنا ولا كلمة هنا\nهو أه طفل لكنه بقى رجل بالإسلام\nوصغر سنه ده كان سبب مهم في اختياره دونا عن أي أحد غيره\nهو مين إللي يفكر إن رسول الله ﷺ وأصحابه مجتمعين في بيت طفل\nوكمان الأرقم كان من قبيلة بني مخزوم والقبيلة دي بتنازع بني هاشم إللي هي قبيلة رسول الله ﷺ على الشرف،\nيعني في بينهم منافسة ،\nفهل من المعقول من وجهة نظرهم إن محمد الهاشمي يكون في بيت واحد من بني مخزوم\nوالسبب الثالث: \nإن بيت الأرقم كان بعيد عن الطريق يعني مكنش في وسط مكة، الناس رايحة جاية عليه،\nكان في حتة مطّرفة كده فمحدش هياخد باله من البيت ده\nشايفين رسول الله ﷺ إزاي بيعلمنا طريقة الأخذ بالأسباب \nأيوة ربنا هو الحافظ لكن لازم أبذل ما في وسعي عشان أحافظ على نفسي\nالدنيا كانت ماشية تمام خلال الثلاث سنين دول،\nلحد ما جاء الأمر من الله لرسوله إنه يجهر بالدعوة\nإزاي جهر رسول الله ﷺ بالدعوة ؟\nوكان إيه رد فعل أهل مكة مع الصادق الأمين؟\nده إللي هنعرف الجزء الجاي إن شاء الله\nhttps://www.facebook.com/groups/710210019782034/?ref=share"}, {"n": 48, "l": "الجزء الرابع عشر | الجهر بالدعوه | و الجزء الخامس عشر | بداية محاربة الدعوه", "u": "https://www.facebook.com/groups/710210019782034/permalink/776342066502162/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الرابعة_عشرة\n#الجهر_بالدعوة\nوقفنا المرة إللي فاتت عند رسول الله ﷺ لما كان بيدعو الناس في السر لمدة ثلاث سنوات،\nفي السنة الأولى من البعثة يُقال إنه اتولد لرسول الله ﷺ ولد وسماه عبد الله،\nلأن الموضوع فيه خلاف بين العلماء، في علماء قالوا إنه اتولد قبل البعثة وعلماء قالوا اتولد بعد البعثة\n وكنا قلنا قبل كده إن أبناؤه كانوا القاسم وزينب وأم كلثوم ورقية وفاطمة، وقلنا إن القاسم مات ومتبقاش غير البنات،\nدلوقتي رسول الله ﷺ رُزق بولد تاني من زوجته خديجة، فهو لم يتزوج غيرها\nفهي حملت تسعة اشهر وولدت ولد تاني بعد أربع بنات وموت الولد الأول، \nفأكيد طبعا الفرحة هتبقى مختلفة ولد على أربع بنات\nعدت الأيام ومات عبد الله، مات وهو صغير\n☆في ناس لو حصل معاها كده تقعد تقول والعياذ بالله طيب ليه بتعطيهولي يارب من الأول لما أنت هتأخذه مني تاني،\nليه تعلقني بيه من البداية...كان بلاشه أحسن\nوطبعا ده إعتراض على قضاء الله، والناس دي مش فاهمة إن الإنسان مش هيأخذ أجر الصابرين غير لما يتعرّض لمواقف شديدة يبان فيها صبره، \nزي الطالب بالضبط، مش هيبان مذاكرته وتفوقه وذكاؤه إلا لما يتحط في الإمتحان\nرسول الله ﷺ لم يعترض ورضي بقضاء الله وكمّل حياته في الدعوة إلى الله، لأن الدنيا مش بتقف على موت أحد\nوكأن ربنا بيقول لنا أهه بشر زيكم ومكنش عنده غير بنات وأولاده الصبيان بيموتوا ، \nعادي يعني الحياة بتمشي...مش نهاية الكون..أيوة الإنسان ممكن يحزن لكن ميخليش الحزن ده يوقّف حياته\nخلال الثلاث سنوات الأولى من البعثة أسلم ستون رجل وامرأة فقط من قبائل متفرقة في مكة،\nيعني لو افترضنا إننا نقسم العدد ده على الثلاث سنوات هنلاقي إن كل سنة بيسلم حوالي عشرين شخص\nوالداعية هو رسول الله ﷺ الصادق الأمين إللي مفيش أحد في أخلاقه ولا في بلاغته ولا في قوة اقناعه،\nومع ذلك أسلم العدد القليل ده\nفما بالنا باللي أقل منه ...كل حاجة حصلت مع رسول الله ﷺ  لها معنى ومغزى،\nوكأن ربنا بيقول لنا اصبروا ومتستعجلوش، الدعوة عايزة صبر وطولة بال،\nإللي أحسن منكم لم يُسلم على إيده غير القليل فمتستعجلوش\nمن الناس إللي أسلمت في الثلاث سنوات دول كان\n《خَبّاب بن الأَرَت》و《مصعب بن عمير》و《عبد الله بن مسعود》و《جعفر بن أبي طالب》و《سعيد بن زيد بن عمرو بن نفيل》\nفاكرين زيد بن عمرو بن نفيل إللي كان موحد على دين إبراهيم عليه السلام وكان مستني نبي آخر الزمان ودعا الله إن ابنه يكون صاحب النبي ده\nوسعيد بن زيد ده كان متزوج من ابنة عمه فاطمة بنت الخطاب أخت عمر بن الخطاب، فأسلمت فاطمة مع زوجها سعيد،\nوكان إللي بيُسلم بيخفي إسلامه،\nوالناس إللي أسلمت دي كان اسمهم الرّعِيل الأول، يعني السابقون إلى الإسلام،\nوكل إنسان رأى رسول الله ﷺ أو اجتمع معه وآمن به واستمر على إيمانه حتى مات رسول الله ومات أو مات هو على الإيمان فده كده اسمه صحابي\nفالستين رجل وامرأة الذين آمنوا برسول الله ﷺ دول اسمهم صَحابة\n☆قبل ما نبدأ في الدعوة الجهرية هنقول قاعدة مهمة لأنها مستمرة معانا في شرح السيرة وكمان دي عقيدتنا كمسلمين وهي:\nإن القرآن الكريم《 كلام الله》 يعني كلام ربنا تكلم به بصوت وحرف ولكن بطريقة تليق بجلاله وكماله،\nولله المثل الأعلى مش احنا بنتكلم كلام عبارة عن صوت وحروف ؟\nأهه برده القرآن ربنا تكلم وقال القرآن ، يعني القرآن مش مخلوق زي السماوات والأرض وزي البشر\nوالقرآن لم ينزل سور كاملة على بعض،\nولكن نزل آيات متفرقة على حسب الاحداث والمناسبات،\nيعني ممكن النهاردة تنزل آية من سورة البقرة، غدا أربعة آيات من سورة الشعراء وهكذا،\nيعني لما كانت تحصل حاجة ربنا يقول لجبريل آيات القرآن وجبريل يأخذ الآيات 《من الله مباشرة》 ويقولها لرسول الله ﷺ،\nيعني ربنا بينَزّل الآيات على جبريل وجبربل ينزلها على محمد رسول الله ﷺ ورسول الله ﷺ يقولها للناس\nلكن مش معنى إن القرآن نزل آيات متفرقة يبقى أي حد يحط أي آية مكان الثانية\nلأن ترتيب الآيات في المصحف توقيفي، يعني رسول الله ﷺ  فقط هو إللي رتبها الترتيب إللي احنا عارفينه ده بوحي من الله\nيعني كان بيقول لكُتّاب الوحي خلوا آية كذا وييجي بعدها آية كذا في سورة كذا،\nوالقرآن كله عبارة عن مائة وأربعة عشرة سورة، نزل منها اثنان وثمانون سورة في مكة،\nالسورة المكية التركيز فيها هيكون على العقيدة\nيعني من هو الله والإيمان بالغيب ويوم القيامة والأحداث إللي هتحصل فيه،\n وكمان هيحكي لهم أحداث الأمم السابقة ويدعوهم للتفكير العقلي المنطقي هل الكلام ده مقنع ولّا لأ\nيعني دي قاعدة ربنا بيضعها لأي إنسان عايز يتعلم الدين،\nتبدأ بالعقيدة يعني تعرف مين هو الله ،\nوإيه هو اليوم الآخر ويعني إيه جنة ونار وشكلهم إيه،\nونتعلم أخبار الأمم السابقة عشان نتعظ ومنقعش في نفس أخطائهم، \nومع ده كله نتدبر في الآيات والكون وفي أحداث حياتنا عشان الإيمان يدخل القلب والعقل\nلأن الإيمان لما يدخل القلب والعقل بيترسخ في الإنسان ويبقى مستحيل أي عوامل خارجية تقدر تؤثر فيه زي ما هنشوف الصحابة وإللي حصل معاهم\nبعد الثلاث سنوات من الدعوة سرا وإسلام الستين رجل وامرأة من قبائل مختلفة، \nربنا أمر رسوله بالجهر بالدعوة لأن دلوقتي بقى في قاعدة نقدر نبني عليها،\nفي أَتباع للدين... أهل مكة مش هيقدروا عليهم لأنهم من قبائل مختلفة وكمان فيهم ناس كثيرة من أشراف مكة\nالجهر بالدعوة كان على مرحلتين:\n◇المرحلة الأولى كانت إنه يجهر بالدعوة بين أقاربه،\nربنا أنزل عليه آية:\n\"وأنذر عشِيرتَك الأقربين\"\nوالحكمة إن رسول الله ﷺ يبدأ بأهله هي إن الأهل بيحبوا أبناءهم بالفطرة وأكثر الناس يحبوا لهم الخير،\nفلو آمن الأهل هيكونوا سند له ويحموه من أي مخاطر ممكن يتعرض لها\nوكمان الأهل أكثر ناس يتقبلوا كلام الداعية وخصوصا لو كان واحد في أخلاق وصدق رسول الله ﷺ إللي الكل مُجتمع على حبه\nرسول الله ﷺ عمل أكل ودعا أعمامه وأبناءهم من باب إنه يؤلف قلوبهم،\nإنتم عارفين الإجتماع على الأكل والكلام والهزار وسط الأكل ده بيعمل جو حلو وبتخلي إللي قصادك يسمع لك\nكان من أعمام رسول الله ﷺ إللي حضروا عمه عبد العزى أو خلونا نقول أبو لهب،\nوكان موضوع الإسلام اتعرف بين أهل مكة، إن محمد بن عبد الله بيقول إنه رسول بيوحى إليه وإنه بيعبد إله مختلف عن الآلهة بتاعتهم،\nفأبو لهب قبل ما رسول الله ﷺ يتكلم بأي كلمة راح قايل :\nأنا بقول لك قصاد أعمامك وأولاد أعمامك، سيبك من الكلام إللي إنت بتقوله ده، احنا مش هنقدر نواجه الناس، إنت عايز تورطنا\nولو فضلت مصمم فاحنا نحبسك أحسن ما يجتمع عليك بطون قريش ومعاهم قبائل العرب فيقضوا عليك،\nأنا مشفتش حد جاء لأهله بشر أكثر من إللي جئت به\nفسكت رسول الله ﷺ ومتكلمش،\nودي حكمة بالغة منه ﷺ، أصل كده هيدخل في جدال معاه ويضيّع هيبة الحق،\nوخصوصا إن إللي قاعدين محدش منهم اتكلم ولا حد عارف أصلا إيه الحكاية\nفالجو مكهرب دلوقتي وأبو لهب له أنصار فالأفضل إننا نقفل الموضوع ونتكلم بعدين\n☆خدوا بالكم إن أبو لهب بيكلم رسول الله ﷺ بالأسلوب ده وهو في بيته لسه واكل من أكله، \nومع ذلك رسول الله ﷺ حتى مقلهوش عيب ده إنت في بيتي إزاي تتكلم كده\nركزوا مع تصرفات رسول الله ﷺ لأنها دين واحنا بنتعلم منه\nمرة ثانية رسول الله ﷺ عمل طعام ودعا أقاربه مرة ثانية،\nطبعا موضوع الأكل ده مُكلف، يعني يُقال إنهم حوالي أربعين رجل \nفرسول الله ﷺ دلوقتي مش بيشتغل ومتفرغ للدعوة\nوالدعوة محتاجة للمال فهيجيب منين الأموال\nزوجته خديجة قالت له إنه يتفرغ للدعوة وهي إللي هتتكفل بالمصاريف،\nيعني خديجة رضي الله عنها كانت بتبذل مالها لخدمة دين الله\nفقبل ما أبو لهب يتكلم بدأ رسول الله ﷺ الكلام، وقيل إنه في الاجتماع التاني ده لم يدعو أبو لهب أصلا،\nالمهم بدأ رسول الله ﷺ يتكلم وقال:\n\"الحمد لله أحمده وأستعينه وأؤمن به وأتوكل عليه، وأشهد أن لا إله إلا الله وحده لا شريك له\"\nطبعا الكلام ده كان صدمة بالنسبة لهم\nوحده لا شريك له\nأمال فين اللات والعزى ومناة وباقي الآلهة\nوأكمل رسول الله ﷺ كلامه:\n\"إن الرائد لا يكذب أهله، والله الذي لا إله إلا هو إني رسول الله إليكم خاصة وإلى الناس عامة، والله لتموتن كما تنامون ، ولتُبعثن كما تستيقظون ، \nولتحاسبُن بما تعملون ، وإنها الجنة أبدا أو النار أبدا\"\n☆جملة الرائد لا يَكذب أهلَه ده مثل عربي معناه إن الشخص إللي بيكون متقدم على القافلة بيبحث عن العشب والماء،\nعمره ما هييجي يكذب على أهله ويخدعهم\nرسول الله ﷺ لخص رسالة الإسلام كلها في الكلمتين دول، إله الكون هو الله وأنا رسوله، وهتموتوا وهتُبعثوا،\nوهتتحاسبوا على أعمالكم وعلى حسب أعمالكم يا إما جنة أبدا أو نار أبدا \nردة فعل أقارب رسول الله ﷺ انقسمت لموقفين:\n◇موقف ابو طالب عم رسول الله ﷺ إللي كان مربيه وبيحبه أكثر من حبه لأبنائه،\nقال له أبو طالب: أنا معاك وهقف جنبك وهدافع عنك،\nفاعمل إللي إنت أُمرت به، فوالله لأعينك وأساعدك وأمنعك من الأذى\nلكن نفسي مش مطاوعاني إني أسيب دين عبد المطلب\n☆يعني أبو طالب تيقن وعرف إن ابن أخيه رسول من عند الله وإنه صادق ومع ذلك لم يؤمن، \nيعني هو خالف الحق بسبب التقاليد وإن ميقدرش يسيب دين أباه،\nوعلى فكرة الموقف ده بيحصل مع الناس في عصرنا\nلما تكلم واحد في الإلتزام ،واتباع أوامر ربنا يقول لك:\nأمي هتزعل، أبويا مش هيرضى، \nأخوتي ...أعمامي و...و...\nوكمان هم عايشين عمرهم كله كده..يعني هم غلط وإنت إللي صح\n◇الموقف الثاني موقف أبو لهب وهو إنه صمم على عدائه لابن أخيه أولا ورسول الله ثانيا\nوقال لهم : امسكوه يا جماعة ووقفوه قبل ما حد تاني هو إللي يوقفه \n☆يعني يقصد اغسلوا عاركم بإيدكم \nفأبو طالب قال: والله لندافع عنه طول ماحنا عايشين\nدي كانت المرحلة الأولى من الدعوة الجهرية،\nالمرحلة الثانية:\nفي يوم من الأيام خرج رسول الله ﷺ من بيته، \nلحد ما وصل جبل الصفا وطلع عليه ووجّه وجهه ناحية الناس وبدأ ينادي على كل أهل مكة بأسماء قبائلهم:\nيااا بني فهر...يااا بني عدي...يااا بني هاشم..ياااا....ياااا\nوالناس سمعت الصوت..إيه ده ..مين إللي بينادي ده\nالصادق الأمين...الصادق الأمين\nأول مرة يعملها يبقى أكيد في حاجة \nفكل الناس بدأت تتجمع وإللي مش عارف يروح يبعت حد من عنده عشان يروح يشوف في إيه\nأول ما الناس اتجمعت قال لهم محمد بن عبد الله بن عبد المطلب ..الصادق الأمين إللي عايش معاهم بقاله أربعين سنة  وعارفينه كويس:\nلو قلت لكم إن في جيش خلف الوادي ده جاي يهجم عليكم ...هل هتصدقوني؟\nقالوا : طبعا احنا منعرفش عنك إلا الصدق وعمرك ما كذبت\nفقال لهم : فأنا نذير لكم بين يدي عذاب شديد\n☆رسول الله ﷺ قبل ما يقول لهم أي حاجة أقام عليهم الحُجة، \nيعني خلاهم يعترفوا بلسانهم إنه صادق وإنهم كانوا هيصدقوه،\nفاللي يخليهم يصدقوه في إنذاره لهم بهجوم الأعداء، فلازم  يصدقوا إنذاره بالعذاب الشديد\n◇في هنا نقطة مهمة عشان الناس إللي دايما بتقول إنتم بتخوفوا الناس من ربنا وتنفروهم، \nوربنا غفور رحيم متقعدوش تخوفوا الناس و...و...\nرسول الله ﷺ أول ما أظهر الدعوة أول حاجة عملها إنه خوف الناس من العذاب\nفي فرق بين إني أخاطب ناس بصفة عامة وإني أدعو شخص دعوة فردية،\nلما أكون بتكلم مع الناس بصفة على اختلاف عقلياتهم يبقى التخويف من العذاب أولا،\nلأن الغفلة والبعد عن ربنا بتكون منتشرة بين الناس،\nفمينفعش واحد غافل غرقان في المعاصي ومش فارق معاه حاجة تيجي تقول له إن الله غفور رحيم\nهتلاقيه ساق فيها وازداد في معاصيه، لكن لو اتخوف هينتبه ويقلق هنا بقى ممكن نستعمل معاه الترغيب،\nلكن لما يكون الخطاب عاااام زي موقف رسول الله ﷺ\nفيبتدي بالتخويف من العذاب عشان الناس تنتبه من غفلتها\nياترى أهل مكة كان ردهم إيه على الصادق الأمين؟\nده إللي هنعرفه الجزء الجاي إن شاء الله\n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الخامسة_عشرة\n#بداية_محاربة_الدعوة\nوقفنا المرة إللي فاتت عند رسول الله ﷺ لما طلع على جبل الصفا وقعد ينادي في الناس ويقول لهم إنه نذير من عند الله،\nوقلنا إن أهل مكة كلهم اجتمعوا عشان يعرفوا في إيه،\nوكان من إللي جاء مع الناس عم رسول الله ﷺ أبو لهب،\nفلما سمع كلام رسول الله ﷺ قال له: تبا لك سائر اليوم هو ده السبب إللي جمعتنا عشانه\nيعني دعا على رسول الله ﷺ بالخسران\nوبدأ يصرف الناس ويبعدهم عنه،\nيعني كأن أبو لهب بيقول للناس بطريقة عملية بصوا أنا مليش دعوة بيه، أنا بوقفه أهه حتى لا تؤذوني معاه وأنا مش راضي عن إللي هو بيعمله\nماهو قال لرسول الله ﷺ من الأول احنا ملناش طاقة بالعرب مش هنقدر نواجههم...مش هنقدر نغير إللي الناس اتعودوا عليه\nفمشكلة ابو لهب الخوف أو خلينا نقول الجُبْن الشديد،\nكان جبان جدا لدرجة إنه رفض الإيمان بالله،\nهو بالنسبة له عادي إنه يقف مع القوي ويعادي ابن أخيه ويخذله عشان يحمي نفسه،\nالإنسان ممكن يخاف كطبيعة بشرية لكن الخوف إللي يوقف الإنسان عن العمل الصالح هو ده الخوف المُهلك\nفربنا أنزل فيه :\n\"تبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ ۩ مَا أَغْنَى عَنْهُ مَالُهُ وَمَا كَسَبَ ۩سَيَصْلَى نَارًا ذَاتَ لَهَبٍ\"\nربنا عالم إن الرجل ده خلاص هيموت كافر، وهنا في إعجاز سبحان الله\nيعني أبو لهب كان بيسمع الآيات دي بتتقال عنه ومع ذلك مقلش مثلا طيب أنا هدخل في الإسلام وأثبت لكم إن القرآن ده كذب،\nوده دليل على إن القرآن من عند عالم الغيب \nوكان أبو لهب بيمشي وراء رسول الله ﷺ وهو بيدعو الناس،\nفيقول للناس متصدقهوش إحنا أهله ..إحنا أعلم الناس به..\nده كاذب ..ده مجنون.. متخلهوش يبعدكم عن دين آباءكم وأجدادكم\nوالناس مستغربة مين الرجل ده \nماشي عمال يكذّب محمد بن عبد الله، ورسول الله ﷺ مش بيرد عليه ولا بيلتفت له أصلا وبيحاول يبعد عنه وده وراه،\nفلما سمع أبو لهب الآيات إللي نزلت فيه راح لأولاده الإثنين\n《عتبة》 و《عُتَيبة》 وكانا متزوجين من ابنتي رسول الله ﷺ رقية وأم كلثوم، وقال لهم لو مطلقتوش بنات محمد لا أعرفكم ولا تعرفوني\n☆خليكم فاكرين اسم عُتَيبة ده عشان له قصة بعدين \nففعلا هم الإثنين طلقوا بنات رسول الله ﷺ،\nتخيلوا لما بنتين يتطلقوا في نفس الوقت، أبوهم هيكون شكله إيه قصاد الناس\nهم بشر على فكرة..بيتألموا وبيتعرضوا لضغط نفسي وكلام الناس بيأثر فيهم،\nومع ذلك رسول الله ﷺ كمل في طريقه،\nومفيش بنت من البنات قالت لأبوها إنت ضيعتنا، ولا احنا اتطلقنا بسببك ولا كانوا حاسين إن طلاقهم ده نهاية العالم..الدنيا بتمشي عادي\n☆ملحوظة بنات النبي كانوا عاقدين بس يعني مكنش لسه حصل بناء وكان سنهم صغير أصلا \nيعني السيدة رقية كان عمرها حوالي من إحدى عشر لثلاثة عشرة عام تقريبا، وأختها أم كلثوم أصغر منها بسنة.\nوطبعا زوجة العم كان لها نصيب هي كمان\nكانت بتجمع الشوك وتشوف فين الطريق إللي هيمشي فيه رسول الله ﷺ وتحطه فيه عشان يدوس عليه ويؤذيه\nفربنا أنزل فيها:\n\"وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ۩فِي جِيدِهَا حَبْلٌ مِّن مَّسَد\"\n☆تخيلوا لما يكون عم الرسول ﷺ وأبناء عمه ومرات عمه بيعملوا معاه كده أمال باقي أهل مكة هيعملوا إيه\nحصل قلق في مكة والدنيا اتقلبت والكل بيتكلم عن الدين الجديد\nوإنتم عارفين إن الموجودين في مكة مش أهل مكة بس، ده في ناس من قبائل تانية بتيجي لمكة،\nفرسول الله ﷺ بدأ يدعوهم هم كمان للإسلام،\nيعني كده الدعوة بدأت بأهله وبعدين بأهل البلد إللي هو عايش فيها وبعدين الناس إللي بييجوا لمكة،\nربنا أمر رسوله بحاجتين:\n\"فَاصْدَعْ بِمَا تُؤْمَرُ وَأَعْرِضْ عَنِ الْمُشْرِكِينَ\"\nيعني ربنا أمره إنه يبلغ الدعوة وفي نفس الوقت لا يقاتل ولا يحارب ولا يهتم باللي المشركين هيعملوه ..يعني تجنب أي صدام مع المشركين...ركز بس في نشر الدعوة \nإللي بيجهر بالدعوة دلوقتي وبيكلم الناس كلهم في كل مكان هو رسول الله ﷺ،\nسادات مكة مش عاجبهم الوضع ...مين ده إللي عمال يتكلم عن آلهتنا بسوء وبيقول إنها لا تضر ولا تنفع\nلازم يتصرفوا وإلا هيبتهم هتروح ومش هيبقى لهم مكانة في مكة\nوأهم حاجة عندهم موضوع الشرف والمكانة ده\nلأن مكنش في حاكم في مكة فكله نفسه يكون الحاكم فكانوا بيجتمعوا مع بعض ويتفقوا على قانون مثلا لأنهم كانوا متساويين تقريبا،\nفكان كل واحد من زعماء القبائل بينافس التاني، عشان يأخذ الحكم وكانوا كلهم متساويين زي ما قلنا،\nفلما يطلع واحد من بني هاشم ويقول إنه نبي يأتيه الوحي من السماء،\nهم هيكون موقفهم إيه؟ دي حاجة مش هيقدروا ينافسوا فيها ..هيقولوا احنا كمان عندنا نبي؟\n◇فكان من أهم أسباب رفضهم لدعوة الإسلام تعصب كل واحد لقبيلته،\nإللي هو إزاي يعني أنا أتبع القبيلة المنافسة وأمشي وراهم واسمع كلامهم\n☆وللأسف في ناس من أعداء الإسلام استخدموا حتة التعصب دي عشان يفرقوا بين المسلمين وبالتالي تضيع الدعوة،\nزي إللي بيتعصب لمذهب معين حتى لو خالف الدليل من القرآن والسنة،\nوزي إللي بيتعصب لجماعة معينة وبيبقى عايز ينصرها وخلاص حتى لو كانت على باطل ويا إما احنا إللي ننصر الدين ونكون إحنا إللي ظاهرين بين الناس يا إما هنخذلكم ونسلمكم للأعداء ونحاربكم،\nوزي إللي بيتعصب لبلده وزي إللي بيتعصب لفريق كرة وغيرها وغيرها،\nوإنتم ممكن تشوفوا الواقع وإنتم تفهموا قصدي\n◇ومن الأسباب إللي منعت الناس برده من الإستجابة لدعوة الإسلام حاجة اتكلمنا عنها في قصص الأنبياء وكانت أول معصية عصي الله بها في السماء، \nواستمرت معانا في كل قصص الأنبياء وبنشوفها مستمر لحد دلوقتي \nفاكرين وصية نوح إللي قالها لابنه\nبالضبط كده منعهم الكِبر \nوالكبر كما قال رسول الله ﷺ:\n\"سَفه الحق - أو بَطَرُ- وغَمْط الناس\"\nسَفه الحق يعني تعرف الحق ثم تنكره، وغمط الناس يعني احتقارهم\nفهم عرفوا إن القرآن ده فعلا كلام مش عادي ، ومع ذلك أنكروا،\nوكانوا محتقرين لرسول الله ﷺ، كانوا بيقولوا : \n\"وَقَالُوا لَوْلا نُزِّلَ هَذَا الْقُرْآنُ عَلَى رَجُلٍ مِنَ الْقَرْيَتَيْنِ عَظِيمٍ\"\nيعني بيقولوا: يا سلام لو كان القرآن ده نزل على رجل عظيم كنا هنؤمن به\nورسول الله ﷺ هو أعظم الخلق وأحسنهم أخلاقا،\nلكن هم عندهم إن العظمة في إن الشخص يكون عنده أموال كثيرة جدا\nفالرجلين إللي كانوا يقصدوهم هما:《 الوليد بن المغيرة 》 من مكة، و《عروة بن مسعود الثقفي》من الطائف،\nومن الأسباب إللي منعت أهل مكة من الإيمان إن رسول الله ﷺ عايز يُحكّم شرع ربنا،\nيعني الشرع هو إللي هيأمر وينهى وده هيأثر على مصالحهم وهيسحب البساط من تحت رجلهم، لأنهم عايزين يمشوا القوانين إللي تخدم مصالحهم\n◇وكمان كانوا خايفين على البلد ماهو محمد ﷺ لو حارب العرب عشان ينشر دعوته،\nالعرب هيفرضوا عليهم حصار مثلا، والبلد الآمن هيتحول  لبلد فتن وحروب ومش هتكون مهيأة للتجارة،\nومكة عايشة على التجارة أصلا فمن وجهة نظرهم هو كده هيضيعهم، فدعوة إيه وإسلام إيه بقى ..احنا عايزين ناكل عيش يابني.. إيه إللي إنت بتقوله ده\n◇وفي ناس رفضت عشان خايفة على شهواتها وملذاتها، \nإنت جايب دين بيأمرني بالعفاف والفضيلة،\nوأنا أصلا شغلي كله في نشر الفواحش والإباحية\n☆ركزوا في الكلام وحاولوا تربطوا بين الواقع بتاعنا في السنوات الأخيرة وبين تفكير أهل مكة وأسبابهم لمحاربة دعوة الإسلام وشوفوا التشابه الشديد،\nودي مش حاجة جديدة الوضع ده مستمر ليوم القيامة لأن دي سنن كونية بس احنا نعرف نتعامل معاها إزاي من غير ما نقع في أخطاء السابقين\n◇وفي ناس منعها غبائها من اتباع الحق تخيلوا \nيعني كانوا يقولوا إزاي يعني نعبد إله واحد..إنت خليت كل الآلهة إله واحد..حاجة عجيبة \n\"أَجَعَلَ الآلِهَةَ إِلَهًا وَاحِدًا إِنَّ هَذَا لَشَيْءٌ عُجَابٌ\"\nإزاي يعني ربنا يُحيينا تاني بعد مانموت \nفمكنوش مقتنعين أصلا بالفكرة ..زي لما نيجي نحاول نقنع حد بدليل واضح وهو مخه متربس\nيابني مينفعش كذا وهو مصمم.. يابني لا يجوز وبالعقل يعني ..وده مفيش\nفكل واحد بقى يدافع عن موقفه باستماتة وعلى الرغم من التنافس إللي كان بينهم إلا إنهم اجتمعوا على حرب الدعوة\n في الوقت ده رسول الله ﷺ مستمر في الدعوة، ومكنش حد يقدر يقتله مثلا لأنه كان في جِوار أبو طالب\nكان في أيام الجاهلية قانون اسمه الإِجَارة يعني الحماية، واحد ضعيف يطلب إنه يدخل في حماية شخص قوي شرفه عالي والناس بتعمل له حساب\nويدافع عنه هو وقبيلته لو أي أحد اعتدى على الشخص المُستجير، وكان الناس أيام الجاهلية بيحترموا جدا موضوع الجوار ده، \nعلى الرغم إن مكنش في قوانين بتحكمهم لكن كلمتهم كانت هي القانون\nفكان رسول الله ﷺ في جِوار أبي طالب عمه الكافر وهو سيد من سادات قريش الناس بتحترمه جدا وبتحترم قبيلة بني هاشم.\n☆ممكن حد يسأل طيب إزاي رسول الله ﷺ يكون في جوار كافر ويطلب منه الحماية\nرسول الله عنده فقه واقع، هو بيستغل أي ظرف لمصلحته ومصلحة نشر الدعوة بشرط مهم وهو إنه لا يتنازل فيها عن أي شيء من دينه\nفالحكمة ضالة المؤمن أنى وجدها فهو أول الناس بها،\nيعني وقت ما المسلم يلاقي حاجة تفيده حتى لو من كافر خلاص يستفيد بها\nزي مثلا اختراع الهواتف النقالة.. الموبايلات يعني، \nإللي اخترعها كافر لكن احنا كمسلمين بنستفيد منها عادي،\nفأي حاجة تفيدنا كمسلمين نستعملها بشرط إنه ميكونش ده مقابل التنازل عن أي حاجة في ديني زي ما هنشوف مع رسول الله ﷺ\n¤وبالمناسبة حديث الحكمة ضالة المؤمن حديث ضعيف لكن معناه صحيح \nفالمشركين في مكة مش قادرين يوقفوا رسول الله ﷺ عن الدعوة، وهو مستمر في الدعوة ليل نهار عليه الصلاة والسلام،\nكان بيروح عند الكعبة ويقرأ عليهم القرآن وبيروح للعبيد والأحرار ويشرح لهم الإسلام،\nمتخيلين واحد ماشي في الطريق عمال يوقف الناس ويشرح لهم الدين \nأظن لو حد عمل كده دلوقتي الناس هتقول عليه مجنون وهيقعدوا يبصوا له نظرات غريبة ومش بعيد يسخروا منه، لمجرد إنه بيدعو لدين الله\nكفار مكة مش عاجبهم الحال فبدأوا يأخذوا خطوات عشان يقضوا على الدين \nأول حاجة عملوها إنهم حاولوا يخلوا الناس إللي بتنصر رسول الله ﷺ على الحياد، مين إللي بينصر رسول الله وبيدافع عنه ؟\nأبو طالب..يبقى خلونا يا جماعة نُحيّده يعني من الآخر نوقفه عن نصرته لابن أخيه،\nراح مجموعة من سادات مكة من المشركين لأبو طالب قالوا له:\nشوف يا أبا طالب ابن أخوك آذانا في مكان اجتماعنا وفي المسجد ، \nهو عايز يعبد ربه خلاص يروح يعبده بعيد عننا ،\nبييجي عندنا ليه في الأماكن بتاعتنا ،فإنت قول له إنه ميجيش ويبعد عننا\nفأبو طالب حس إن الكلام منطقي..إيه إللي يودي ابن أخوه هناك ..هي الدنيا ناقصة مشاكل..بيروح يستفزهم ليه\nفراح أبو طالب لرسول الله ﷺ وقال له:\nإن قومك هؤلاء اشتكوا عليك، وقالوا إنك بتروح مجالسهم وبتؤذيهم،\nفبلاش تروح عندهم وتقول الكلام إللي بتقوله \nفقال لهم رسول الله : شايفين الشمس؟ \nقالوا : أه\nفقال رسول الله ﷺ :\n\"ما أنا بأقدر أن أدع ذلك منكم أن تشعلوا منها شعلة\"\nيعني زي ما انتم متقدروش تشعلوا من الشمس شعلة أنا كمان مقدرش أسيب الدين ده\nفأبو طالب لما شاف ثبات رسول الله ﷺ اتأثر بكلامه وراح قايل لهم:\nوالله ابن أخويا ده ميكذبش أبدا، ارجعوا يا جماعة وسبوه أنا هفضل أدافع عنه \n☆حديث: \"يا عم لو وضعوا الشمس في يميني والقمر في يساري على أن أترك هذا الدين ما تركته \" \nده حديث ضعيف \nفرسول الله ﷺ بيعلمنا إننا طول ماحنا ثابتين على موقفنا وعندنا ثقة في الله وفي الدين موقفنا ده هيأثر في إللي حوالينا إنهم يشجعونا ويقفوا جنبنا،\nلكن لو الإنسان كان متردد في كلامه ومش واثق أوي هتلاقي إللي حواليك بيضغطوا عليك لحد ماتعمل إللي هم عايزينه\nكده أول مرحلة منفعتش \nندخل في مرحلة الحوار والإغراء بالعروض\nفقالوا خلونا نتكلم معاه يمكن نقنعه ،فاختاروا واحد منهم عشان يروح يعرض على رسول الله ﷺ شوية عروض،\nفاختاروا عتبة بن ربيعة سيد من سادات مكة ،فراح لرسول الله ﷺ عشان يكلمه،\nقال له: يا محمد ! إنت عارف مكانتك إيه بيننا ، ونسبك إيه في مكة، وإنت جيت بأمر عظيم فرقت به بيننا ،\nوعِبت في آلهتنا وديننا وكفّرت آباءنا وأجدادنا،\nفأنا هعرض عليك شوية عروض فكر فيها يمكن تقبل حاجة منها\nفقال له رسول الله ﷺ: قل يا أبا الوليد .\n☆وأبو الوليد كانت كنية عتبة بن ربيعة \nفقال عتبة:\nيا ابن أخي، لو إنت عامل القلق ده كله عشان محتاج أموال،\nقول واحنا هنجمع لك أموال لحد ما تكون إنت أكثر الناس مالا،\nولو إنت عايز شرف هنخليك سيد مكة، منخدش قرار غير لما نرجع لك، ولو إنت عايز مُلك ..هنخليك ملك مكة تحكم زي مانت عايز،\nولو إللي بيجيلك ده مس من الجن هو إللي بيخليك تقول الكلام ده هنجيب لك أحسن الأطباء حتى لو دفعنا كل ما نملك لحد ما تخف\nكل ده ورسول الله ﷺ يسمع ..مقطعهوش ولا مرة،يعني هو عمال يتهمه باتهامات باطلة ورسول الله ﷺ بيسمع،\nفبعد ما خلص قال له رسول الله ﷺ: خلصت كلام؟\nفقال له عتبة خلصت\n فقال له رسول الله : فاسمع مني\nوبدأ رسول الله ﷺ يقرأ القرآن من بداية سورة فُصّلت:\n\"حم ۩ تَنْزِيلٌ مِنَ الرَّحْمَنِ الرَّحِيمِ ۩ كِتَابٌ فُصِّلَتْ آيَاتُهُ قُرْآنًا عَرَبِيًّا لِقَوْمٍ يَعْلَمُونَ ۩ بَشِيرًا وَنَذِيرًا فَأَعْرَضَ أَكْثَرُهُمْ فَهُمْ لَا يَسْمَعُونَ \" \nواستمر رسول الله ﷺ يقرأ ويقرأ وعتبة يستمع للآيات،\nبيسمع القرآن بصوت رسول الله ﷺ مباشرة متخيلين\nفلما وصل رسول الله ﷺ عند آية:\n \"فَإِنْ أَعْرَضُوا فَقُلْ أَنْذَرْتُكُمْ صَاعِقَةً مِثْلَ صَاعِقَةِ عَادٍ وَثَمُودَ \"\nفهنا عتبة خاف وقام ووضع إيده على فم رسول الله ﷺ وقال :\nناشدتك الله والرحم ..ناشدتك الله والرّحم.\nيعني بيستحلفه بالله وصلة الرحم إللي بينهم إنه ميخليش \nربنا يعمل فيهم زي ما عمل في قوم عاد وثمود.\n☆فاكرين قصتهم \nفأكمل رسول الله ﷺ تلاوة باقي السورة لحد ما وصل لأية السجدة وسجد،\nوقال لعتبة: هذا ما عندي.\nفقام عتبة من عند رسول الله ﷺ ورجع لأصحابه إللي كانوا مستنيين الأخبار،\nأول ماشافوه جاي عليهم في حالة ذهول ..وشه متغير..قالوا والله عتبة راجع لكم بغير الوجه الذي ذهب به\nإيه جرى لك يا أبا الوليد\nقال لهم: ......المرة الجاية إن شاء الله نعرف قال لهم إيه\n☆https://www.facebook.com/groups/710210019782034/?ref=share"}, {"n": 49, "l": "الجزء السادس عشر | الحرب الإعلاميه علي الدعوه | والجزء السابع عشر | بداية تعذيب المسلمين", "u": "https://www.facebook.com/groups/710210019782034/permalink/776359509833751/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_السادسة_عشرة\n#الحرب_الإعلامية_على_الدعوة\nكنا واقفين المرة إللي فاتت عند عتبة بن ربيعة لما راح لرسول الله ﷺ وعرض عليه شوية عروض في مقابل إنه يسيب الدعوة إلى الإسلام،\nلكن رسول الله ﷺ كل إللي عمله إنه قرأ عليه القرآن،\nفعتبة بعد ما سمع القرآن من رسول الله ﷺ رجع لسادات مكة إللي كانوا منتظرينه عشان يعرفوا نتيجة الحوار،\nفلما شافوه وهو جاي وكان وجهه متغير وسألوه إيه إللي حصل قال لهم:\nأنا سمعت كلام عمري ما سمعت مثله أبدا\nوالله ماهو كلام شعر ولا هو كلام سحر ولا كهانة\nيامعشر قريش اسمعوا كلامي وخذوا نصيحتي \nسيبوا الرجل يدعو الناس ومتقفوش في طريقه، فوالله ليكون للكلام إللي سمعته منه ده حاجة عظيمة في المستقبل\nفلو حصل والعرب قتلوه خلاص يبقى همّ كفوكم شره وخلصنا منه،\nولو ظهر عليهم وانتصر فملكه ملكُكم ..لأنه من قريش وعزه عزكم، وهتكونوا أسعد الناس به\n☆أظن مفيش كلام منطقي عقلاني أكثر من كده\nفقالوا له: والله محمد سحرك بكلامه يا أبا الوليد\nفقال لهم : ده رأيي وانتم أحرار اعملوا إللي تعملوه\nعلى الرغم من إن عتبة عارف إن رسول الله ﷺ على حق لكنه برده لم يؤمن\n☆احنا نستفيد من الحوار ده نقطتين مهمين: \n◇أولا:\n إزاي إن رسول الله ﷺ عرف يكسب عتبة بن ربيعة بأسلوبه وحوّله لداعية يدعو أصحابه بفن الإصغاء\nيعني عتبة لما جاء لرسول الله ﷺ وقعد يكلمه بكلام يُعتبر إهانة وكله اتهامات باطلة، ومع ذلك رسول الله ﷺ لم يقاطعه ولا مرة لحد ما خلص كلامه،\nرسول الله ﷺ عارف إنه لما يقعد يسمع لكلام عتبة من غير ما يقاطعه ده هيديله فرصة إنه يعرف دماغ إللي قصاده بيفكر إزاي ويعرف يرد عليه بالكلام إللي يناسب شخصيته\nيعني اشمعنى رسول الله ﷺ قرأ على عتبة سورة فُصلت بالذات ومقرأش غيرها؟\nلأنه فهم من شخصية عتبة إن آيات سورة فصلت هيكون لها الأثر الأكبر على عقليته\nوكمان لما رسول الله ﷺ كان بيسمعه ومكنش بيقاطعه، ده خلى عتبة يتجاوب مع رسول الله ﷺ لما قال له اسمع مني،\nفكان لازم عتبة يسمع من رسول الله ﷺ بدون مقاطعة زي ما رسول الله ﷺ سمعه بدون مقاطعة \nده غير إن الواحد لما يسمع للي قصاده وخصوصا لو كان غضبان أو متحفز بدون مقاطعة فده بيخليه يهدى ويرجع لعقله،\nبعكس لو قعدنا نقاطعه هتلاقيه بيتعصب أكثر وبيزعق أكثر،\nفعتبة كان جاي متحفز ومتعصب،\nحتى أصحابه قالوا إنه رجع بوجه تاني خالص غير إللي راح لرسول الله ﷺ به\nفرسول الله ﷺ بيعلمنا إن ممكن مشكلة كبيرة يكون حلها في إننا نسمع الشخص ده بيقول إيه من غير ما نقاطعه،\nحتى لو الشخص ده بيعيب فينا وبيتهمنا اتهامات باطلة زي ما عتبة عمل مع رسول الله ﷺ\nجربوها كده.. فقد كان لكم في رسول الله أسوة حسنة\n◇ثانيا:\nإن أهل الباطل دائما وأبدا مفكرين كل الناس زيهم ممكن يبيعوا دينهم ودعوتهم في مقابل شوية أموال أو مناصب،\nأيوة في ناس بتقبل وشفناهم \nلكن الداعية الحق الثابت الراسخ في إيمانه زي رسول الله ﷺ عمره ما يقبل أبدا التنازل عن دينه في مقابل أي حاجة من متاع الدنيا الزائل\nلأنه فاهم الدين فعلا صح وعارف إن الدنيا كلها لا تساوي عند الله جناح بعوضة، \nلكن إللي بيقبل متاع الدنيا الزائل في مقابل التنازل عن دينه وعن دعوته وساعات كمان يحرف في الدين ويقول كلام باطل ، ده مكنش فاهم الدين ولا كان راسخ فيه أصلا\nكده المرحلة الثانية من المراحل السلمية لصد دعوة الإسلام وهي الإغراء بالعروض فشلت \nندخل المرحلة الثالثة وهي تشويه صورة الداعية \nحملة إعلامية لتشويه صورة رسول الله ﷺ أمام الناس \nلأن لو شوهنا صورة الداعية الناس هتفقد الثقة فيه ومحدش هيصدق الكلام إللي بيقوله، \nفمش هيلاقوا حد ياخدوا منه الدين ويبقى خلينا الناس نفسها هي إللي تقضي على دين محمد \nبس همّ مش هيقولوا أي كلام كده..لازم يكونوا متفقين على الكلام مع بعض عشان الناس متقولش ده كلامهم متناقض ويبقى الكلام مختلف فيكذب بعضهم بعض\nوكان الزعيم إللي بيخطط بالذكاء ده هو\n《الوليد بن المغيرة》\n☆الرجل الأول إللي أهل مكة قالوا عنه عظيم ولو نزل القرآن عليه كنا آمنا به،\nفهو كان شيخ كبير من حكماء العرب، وكان لقبه ريحانة العرب، وكانوا بينشدوا أمامه الأشعار فكان إللي يختاره من الشعر؛ الناس تقدمه ويبقى مُفضل عندهم\nفكان بيقول لأهل مكة اتفقوا على رأي واحد وكلام موحد نقوله للناس في كل القنوات ...قصدي في كل مجالس أهل مكة\nفقالوا له: قلنا إنت رأيك يا أبا عبد شمس نقول إيه\n☆أبو عبد شمس كنية الوليد بن المغيرة.\nفقال لهم: لا إنتم قولوا خلوني أسمع إللي عندكم الأول\nفقالوا له : خلونا نقول كاهن\nفقال لهم: لا لا ..هو مش كاهن أنا شفت الكُهّان وعارف كلامهم وسجعهُم ...الناس مش هتقتنع ...غيره\nفقالوا: يبقى مجنون \nفقال لهم: مش مجنون ..احنا شفنا المجانين وعارفينهم\nفقالوا : يبقى شاعر \nقال لهم: لأ..كلامه ليس شعر ..احنا عارفين كل أنواع الشعر...ده احنا أهل الشعر\nقالوا : بااااس يبقى ساحر\nفقال لهم: لأ..حتى مش ساحر...احنا شفنا السحرة وسحرهم عامل إزاي، فكلامه مختلف تماما عن طلاسم السحرة \nفقالوا له: \nخلاص إنت إيه رأيك ..احنا قلنا كل إللي عندنا\nفقال لهم: بصراحة ...إن لقوله لحلاوة ..وإن عليه لطلاوة وإن أعلاه لمثمر وإن أسفله لمغدق وإنه ليعلُو ولا يُعلى عليه\n=نعم\nهو إنت في صفه ولا في صفنا\nوكان الوليد بن المغيرة سمع القرآن مرة من رسول الله ﷺ،\nفهو مقدرش يمسك نفسه من إنه يقول إللي حس بيه،\nفهو بيقول إن القرآن بيجذب النفوس، وبترتاح له الأرواح، مُحلى بألفاظ جميلة وأنغام مقبولة،\nعامل زي الشجرة الكبيرة غصونها مليانة بالثمار، وجذورها مستحكمة في الأرض واسعة الانتشار في أعماق الأرض.\nفهو عارف دلوقتي إن القرآن ده فعلا مش من قول البشر، فأي كلام هيتقال ضد رسول الله ﷺ، الناس هتعرف إنه غير صحيح،\n=طب والحل\nقعد يفكر لحد ما قال لهم: \nأحسن حاجة نقول إنه ساحر \nلكن السحر بتاعه مختلف ..مستواه أعلى ..سحره بيفرّق به بين الرجل وأبيه، وبين الرجل وأخيه وبين الرجل وزوجته وهكذا\nيعني هم قاعدين بيفكروا ويخططوا ويمكروا ويدبروا  المكائد وناسيين حاجة مهمة أوي\n\"أَلَمْ يَعْلَم بِأَنَّ اللَّهَ يَرَىٰ\"\nناسيين أو متناسين او مش مستوعبين إن ربنا يراهم وسامعهم وعالم بكل صغيرة وكبيرة\nفأنزل الله عالم الغيب والشهادة الآيات على رسول الله ﷺ تعرّفه إيه إللي بيحصل بالضبط:\n\"ذَرْنِي وَمَنْ خَلَقْتُ وَحِيدًا ۩ وَجَعَلْتُ لَهُ مَالًا مَمْدُودًا ۩وَبَنِينَ شُهُودًا۩ وَمَهَّدْتُ لَهُ تَمْهِيدًا ۩ثُمَّ يَطْمَعُ أَنْ أَزِيدَ۩كَلَّا إِنَّهُ كَانَ لِآَيَاتِنَا عَنِيدًا ۩سَأُرْهِقُهُ صَعُودًا \"\nلدرجة إن ربنا وصف لرسول الله ﷺ نفسية الوليد كانت عاملة إزاي\n\"إِنَّهُ فَكَّرَ وَقَدَّرَ ۩ فَقُتِلَ كَيْفَ قَدَّرَ ۩ ثُمَّ قُتِلَ كَيْفَ قَدَّرَ ۩ثُمَّ نَظَرَ ۩ثُمَّ عَبَسَ وَبَسَرَ۩ ثُمَّ أَدْبَرَ وَاسْتَكْبَرَ ۩\n فَقَالَ إِنْ هَذَا إِلَّا سِحْرٌ يُؤْثَرُ۩إِنْ هَذَا إِلَّا قَوْلُ الْبَشَرِ\"\nفربنا قال في الآخر إن مصيره هو وأي أحد بيحارب الدعوة زيه كده من غير ما يتوب هو النار\n\"سَأُصْلِيهِ سَقَرَ\"\nومع كل التخطيط والمآمرات والاجتماعات و...و...\nوفي المقابل رسول الله ﷺ إمكاناته ضعيفة،\nومع ذلك كانوا غير مُوفقين لأنهم بيحاربوا الله، والحق بيوصل للناس وربنا بيفضح كل مؤامراتهم \nولم يكتفوا بتشويه صورة رسول الله ﷺ، ده بدأوا يشوهوا رسالة الإسلام نفسها \nبقوا يقولوا الكلام إللي محمد بيقوله ده هو إللي مؤلفه بمساعدة ناس تانية\n\"وَقَالَ الَّذِينَ كَفَرُوا إِنْ هَٰذَا إِلَّا إِفْكٌ افْتَرَاهُ وَأَعَانَهُ عَلَيْهِ قَوْمٌ آخَرُونَ\"\nوشوية يقولوا ده بيقول أساطير، يعني ناقل من كتب الأولين ،\nمع إنهم عارفين كويس إن رسول الله ﷺ أُمّي..مبيعرفش يقرأ ولا يكتب وهو قاعد في مكة طول عمره مكنش بيخرج منها إلا نادرا،\n\"وقَالُوا أَسَاطِيرُ الْأَوَّلِينَ اكْتَتَبَهَا فَهِيَ تُمْلَىٰ عَلَيْهِ بُكْرَةً وَأَصِيلًا \"\n☆ملحوظة مهمة\nرسول الله ﷺ كان أُمّي يعني مكنش بيعرف يقرأ ولا يكتب،\nيعني مش إن أمي نسبة إلى أم القرى والكلام ده\nوالدليل قول الله: \n\"وَمَا كُنْتَ تَتْلُو مِنْ قَبْلِهِ مِنْ كِتَابٍ وَلا تَخُطُّهُ بِيَمِينِكَ إِذًا لارْتَابَ الْمُبْطِلُونَ\"\nوقوله: \n\"فَآمِنُوا بِاللَّهِ وَرَسُولِهِ النَّبِيِّ الْأُمِّيِّ \"\nوكلمة أُمّي في الآية هنا معناها من لا يقرأ ولا يكتب\nوفي ناس كثيرة حاولت تشكك في أمية رسول الله ﷺ،\nولكن الأدلة من القرآن والسنة قاطعة إن رسول الله ﷺ كان أُمّيا لا يعرف القراءة ولا الكتابة\nوادعى المشركين إن إللي بيعلم رسول الله ﷺ القرآن غلام نصراني، \n\"وَلَقَدْ نَعْلَمُ أَنَّهُمْ يَقُولُونَ إِنَّمَا يُعَلِّمُهُ بَشَرٌ ۗ لِّسَانُ الَّذِي يُلْحِدُونَ إِلَيْهِ أَعْجَمِيٌّ وَهَٰذَا لِسَانٌ عَرَبِيٌّ مُّبِينٌ \"\nوقعدوا يطعنوا في فكرة البعث ...يعني إيه إننا هنحيا تاني بعد الموت، \n\"وَقَالَ الَّذِينَ كَفَرُوا هَلْ نَدُلُّكُمْ عَلَىٰ رَجُلٍ يُنَبِّئُكُمْ إِذَا مُزِّقْتُمْ كُلَّ مُمَزَّقٍ إِنَّكُمْ لَفِي خَلْقٍ جَدِيدٍ\"\nالكلام واضح فيه السخرية الكاملة\nوالمحاولات دي مكنتش يوم ولا يومين ولا شهر ولا شهرين دي قعدت سنين،\nوالصوت العالي للباطل بيشتت عقول الناس وبيخليهم يصدقوا الكلام الغلط مع كثرة الزن عليهم\nده الإسلام ده جه عشان يفرق بين الناس ، ويخلي الناس عبارة عن فِرق ويعمل عدوات بينهم\nإيه يعني لما كلنا نعيش مع بعض في سلام والدين لله والوطن للجميع ....وكل واحد على دينه الله يعينه\nوكمان مع ما سبق خلونا نُشغِل الناس بشوية حاجات كده عشان قلوبهم تبقى غرقانة بالشهوات واللهو والتفاهة ،\nلأن لما يكون القلب منشغل بالباطل صعب إنه يستجيب لدعوة فيها إصلاح\nيعملوا إيييه\nهاتوا يا جماعة النّضْر بن الحارث نخليه يقعد بين الناس ويحكي لهم حكايات وروايات ومسلسلات وأساطير ، \nوينوع بقى ما بين كوميديا على رومانسية على إباحية على شوية غموض، ومفيش مانع من الأغاني برده،\nماهو احنا لازم نرضي جميع الأذواق ..أمال إيه\n☆مين أصلا النّضر بن الحارث ده\nده كان رجل من كفار مكة لما رسول الله ﷺ أعلن الدعوة إلى الله،\nراح مسافر للحِيرة في العراق وقعد يتعلم كتب الفرس ويحفظ القصص بتاعتهم زي كتاب 《كليلة ودمنة》 إللي هيترجمه للغة العربية ابن المقفع بعدين في العصر العباسي\nوكان بيسافر كمان للشام وبلاد فارس بحكم التجارة فكان بيتعلم أساطير الروم ،\nوخالط أهل  الكتاب واتعلم منهم، واتعلم عزف العود واشترى واحد وجاء به لمكة، وأهل مكة مكنوش يعرفوا العود،\nيعني عمل لنفسه خليط كده محترم ورجع لمكة عشان ينشر الثقافة الجديدة \nفكان يقعد في الأماكن إللي رسول الله ﷺ بيدعو الناس فيها ويخبرهم عن قصص الأنبياء السابقين وعن عاد وثمود ،\nويحكي لهم النضر بن الحارث عن القصص المشوقة من قصص فارس والروم ويقول لهم:\nمحمد أحسن مني في إيه؟ هو بيحكي عن عاد وثمود وأنا بحكي عن فارس والروم\nاحنا سمعنا كلامه ولو عايزين هنقول زي ما بيقول، وكلامه كله من أساطير الأولين اتعلمها زي مانا اتعلمتها \nفأنزل الله فيه:\n\"وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا قَالُوا قَدْ سَمِعْنَا لَوْ نَشَاءُ لَقُلْنَا مِثْلَ هَذَا إِنْ هَذَا إِلا أَسَاطِيرُ الأَوَّلِينَ \"\nولما كان يعرف إن في أحد عايز يدخل الإسلام كان بيروح له  ومعاه العود ويقعد يغني له ويقول له الغناء والموسيقى أفضل من الصلاة والصيام واتباع دين محمد،\nفنزلت فيه آية:\n\"وَمِنَ النَّاسِ مَن يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَن سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّخِذَهَا هُزُوًا ۚ أُولَٰئِكَ لَهُمْ عَذَابٌ مُّهِينٌ\"\nوكان هو أول من أدخل العزف بالعود لمكة وهو إللي علمهم،\nواشترى المغنيات عشان يلهي الناس بها،\nومكنش أهل مكة يعرفوا الغناء والألحان لحد ما جاء النضر وكان أول من ضرب على العود بألحان الفرس\n☆ممكن حد يسأل إزاي يعني الناس تسيب القرآن وتروح تسمع للنضر ده وواضح طبعا إن القرآن مختلف وأحسن\nبكل بساطة زي ما الناس دلوقتي سايبة القرآن ومشغولة بالمسلسلات والروايات والأفلام من هنا ومن هنا،\nوبالأغاني والإباحية والمنكرات والمحرمات إللي بقت متاحة بضغطة زرار في أي وقت\nوكل ده عشان يلهوا الناس عن الدين ، أمال نسيبهم يفوقوا ويقولوا عايزين الإسلام\nالقلب المشغول بالباطل لا يمكن إنه ينصر حق\nخطة النضر بن الحارث كانت من أكثر من ألف وأربعمائة سنة وهي متكررة وشوفوا حالنا دلوقتي هتلاقوا الخطة دي بتتطبق بالضبط\nالتاريخ بيعيد نفسه ولأن الناس متعرفش حاجة عن تاريخها فهتلاقيهم بيقعوا في نفس إللي وقع فيه السابقين\nقريش لسه عندها حيل ثانية بجانب الحيل السابقة،\nاستخدموا الضغط النفسي على أتباع رسول الله ﷺ،\nقالوا كل واحد يشوف إللي أسلم من أهله ويقنعهم إنهم  يسيبوا الدين ده ويبعدوا عن محمد،\nاسمعوا كلامنا لأن الكلام ده لمصلحتكم ومصلحة عيالكم\nوكان معظم إللي أسلموا شباب،\nزي سعد بن أبي وقاص ومصعب بن عمير مثلا ، فأم سعد حاولت معاه تقنعه من هنا لهنا مفيش،\nراحت مستعملة عنصر الترهيب، فقالت لابنها: \nأنا مش هاكل ولا أشرب إلا لما تسيب الإسلام، خليني أموت بقى والعرب تُعيرك بأنك قاتل أمك\nوسعد بن أبي وقاص كان أبر الناس بأمه، وكان معروف بين الناس بالبر ده\nوده ضغط نفسي رهيب على شاب صغير، فقال لها بكل بساطة: \nوالله يا أماه لو كانت لك مائة نفس فخرجت نفسا نفسا ما تركت ديني هذا، فكلي أو متاكليش\nفعرفت من ثباته وكلامه إنه مش هيغير دينه،\nفأكلت أمه وهو بقي على الإسلام\n☆وهنا رسالة من سعد بن أبي وقاص لكل واحد بيعصي الله عشان يرضي أمه أو أبوه\nربنا إللي أمرنا ببر الوالدين هو نفسه إللي أمرنا إن لما يكون حاجة متعلقة في الدين يبقى ننفذ أمر ربنا \nوإن ثبات الإنسان وإصراره على موقفه وإنه مش فارق معاه إيه إللي ممكن يحصل، بيخلي إللي قصادك يستسلم وينزل على رأيك،\nغير لو حس إنك متردد أو معندكش الثبات اللازم، هتلاقيه بيضغط عليك لحد ما ترجع عن هدفك\nوالمثال الثاني هو مصعب بن عمير، إللي كان من أكثر شاب مكة رقة وثراء، كان مُنعم وأمه كانت بتحبه جدا، وكانت غنية،\nوكانت بتشتري له أفخم الملابس والعطور وكان أكثر شباب مكة ترفا، وطبعا مكنش بيشتغل،\nفلما أسلم أمه منعت عنه كل ده وكمان طردته من البيت،\nوبقى فقير وبقي يلبس الملابس الخشنة ،وجلده كان بيتقشر زي جلد الثعبان\nولما كان يمشي مدة كانت رجله بتجيب دم، ماهو مش متعود على حياة البهدلة والفقر\nلدرجة إن الصحابة كانوا بيبكوا لما بيشوفوه كده، وهو مع ذلك مكنش في دماغه ولا مهتم،\nاحنا بس بنسمع قصته لكن هو عاش الحياة دي وعمره ماشتكى،\nولا مَنّ على ربنا ولا على رسوله ولا قال للصحابة أنا كنت وكنت وسيبت كل ده عشان الإسلام زي ما في ناس بتعمل للأسف\nإيه إللي يخلي شاب يسيب النعيم إللي كان فيه ده وإللي أي شاب يتمناه؟\nإيه إللي يجبره إنه يعرض نفسه للأذى ده كله؟\nهيستفيد إيه وهو عنده الدنيا كلها؟\nالدافع إللي خلاه يسيب أحسن الأكلات وأحسن اللبس ويتعرض للعذاب الجسدي ويصبر عليه وكأنه ولا حاجة ، هو إنه عايز الدار الآخرة،\nمشكلة الناس دلوقتي إنها عايزة الدنيا والآخرة في نفس الوقت، \nومع أول اختبار أو ضغط نفسي للأسف تلاقيها أول حاجة تفرط فيها هي دينها،\nوناسيين إن الدنيا دار ابتلاء ودار تنازلات عن إللي بنحبه سواء أموال أو أهل أو أصحاب أو وطن في مقابل رضا الله،\nوهنشوف إزاي الصحابة عملوا كده فعلا\nكل الوسائل دي مقدرتش إنها تقضي على الدعوة للإسلام،\nولقوا إن الناس ثابتة وبتزيد\nفلجأوا بقى للوسيلة إللي كل ظالم على مر العصور بيلجأ لها ،\nوسيلة التعذيب والتهديد بالقتل والقتل فعلا\nعمل إيه كفار قريش مع المسلمين؟\nوكان إيه رد فعل المسلمين؟\nوكان إيه رد فعل رسول الله ﷺ نفسه على حملة التعذيب دي؟\nده إللي هنعرفه الجزء الجاي إن شاء الله \n#تعديل\nبقالي يومين مش متابع أخبار خالص ومركز في كتابة السيرة،\nفبفتح الفيس لقيت موضوع إعدامات الشباب التسعة ، \nبقدر ربنا يكون جزء النهاردة عن تعذيب وقتل المسلمين الأوائل، ياريت تقرأوا الجزء ده وتحاولوا تنشروه بين الناس،\nعشان نعرف إن الإبتلاء في الله سنة كونية وشوفوا رد رسول الله على خباب بن الأرت\n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_السابعة_عشرة\n#بداية_تعذيب_المسلمين\nكنا واقفين عند قريش ومحاولاتها لصد الدعوة الإسلامية،\nوقلنا الوسائل إللي استعملها كفار قريش في كده، زي تحييد أنصار الدعوة ،\nوالإغراء بالعروض المادية ،وتشويه صورة الداعية وتشويه صورة الدعوة نفسها وشغل الناس بالباطل عن طريق النضر بن الحارث،\nوآخر حاجة كانت استعمال الضغط النفسي من الأهل على أقاربهم إللي أسلموا زي سعد بن أبي وقاص ومصعب بن عمير\nلما كفار مكة لقوا إن مفيش حاجة جايبة نتيجة قالوا بس، احنا نعذب الناس إللي أسلمت دي لحد ما يرجعوا عن دينهم\nفكل واحد من سادات مكة يشوف إللي أسلم من قبيلته وهو إللي يعذبه، \nفبدأ كل واحد يشوف مين إللي أسلم من قبيلته ويعذبه،\nحر أو عبد\n=عثمان بن عفان كان عمه بيلفه في حصير من ورق النخيل يكتفه يعني وبعدين يشعله من تحته ويطلع دخان على وشه لحد ما كان كأنه بيموت من الخنقة،\nالواحد لما يشم شوية دخان بس من بعيد بيبقى مش قادر يتنفس، \nده بقى الدخان تحته وطالع على وشه كله\n=بلال بن رباح كان عبد من الحبشة يملكه واحد من السادة اسمه أمية بن خلف،\nفكان يحط في رقبته حبل ويعطي الحبل للصبيان يلعبوا به،\nيشدوه ويوقعوه،\nوكانوا بيطلعوه وقت الظهر في صحراء مكة وينيموه على الرمل الساخن ويضعوا على صدره صخرة كبيرة جدا، \nووقت الظهر في مكة في الصيف في الصحراء درجة الحرارة ممكن تعدي الخمسين\nوكانوا يقولوا له:\nهنسيبك كده لحد ما تموت أو ترجع عن دين محمد وتعبد اللات والعزى\nوهو يقول لهم : أحد أحد\nفكانوا بيتغاظوا منه ويزودا عليه العذاب وهو ميسكتش يغيظهم برده ويقول لهم أحد أحد\nيعني الله واحد\nوكان يقول لهم وهو بيتعذب : \nوالله لو أعرف كلمة تغيظكم أكثر من الكلمة دي كنت قلتها\nوالكلام ده مكنش يوم ولا يومين ده كان فترات طويلة،\nاحنا بس مجرد تخيل الموقف بنحس بوجع القلب،\nأمال إللي حصل معاه كده كان ألمه عامل إزاي\nوفضلوا يعذبوا فيه لحد اشتراه أبو بكر صاحب رسول الله ﷺ من أمية بن خلف واعتقه لوجه الله.\n=عمار وأبوه ياسر وأمه سمية ،\nوكان ياسر شيخ كبير في السن وكان بيعذبه واحد من سادات بني مخزوم قبيلة الوليد بن المغيرة اسمه《عمرو بن هشام》 إللي كنيته أبو جهل\nفكان أبو جهل هو المسؤول عن تعذيب الشيخ الكبير ياسر،\nوزوجته المرأة العجوز سمية، وكانوا بيطلعوهم في الصحراء ويعذبوهم في الحر ، \nوطبعا مفيش لا أكل ولا مية، وكان رسول الله ﷺ بيعدي عليهم وهم بيُعذبوا ويقول لهم:\n \"صبرا آل ياسر فإن موعدكم الجنة\"\n فياسر مات تحت التعذيب وأبو جهل قعد يعذب في سمية وقال لها : إنتِ إزاي تسيبي آلهة آبائك وتتبعي محمد، وريني إلهك إللي بتعبديه ده\nفقالت له: لا تدركه الأبصار وهو يدرك الأبصار وهو اللطيف الخبير\nفراح ماسك حَرْبة وطعن سمية في موضع عفتها، يعني في فرجها من الأمام فماتت \nوكانت أول شهيدة في الإسلام، ومتبقاش غير عمار...شاف أبوه قتل تحت التعذيب وشاف أمه طعنت وماتت،\nوهو نفسه بيتعذب أشد العذاب، كانوا ساعات يلبسوه الدروع الحديدية في شدة الحر،\nوساعات يحطوا على صدره صخر أحمر ثقيل ، وساعات يحطوه داخل بئر ويغطوه بالماء،\nفكان من شدة التعذيب كان بيوصل لمرحلة إنه مش بيبقى عارف هو بيقول إيه\nفقالوا مش هنسيبك غير لما تشتم محمد وتمدح الآلهة بتاعتنا\nفمع شدة التعذيب قال لهم عمار إللي طلبوه منه فتركوه،\nوراح عمار لرسول الله ﷺ وهو حزين فسأله رسول الله: إيه إللي حصل معاك؟\nفقال عمار والله يا رسول الله لم يتركوني إلا لما شتمتك ومَدَحت آلهتهم\nفسأله رسول الله ﷺ : وحال قلبك إيه؟\nهل إنت راضي بالكلام إللي قلته ولا رافض؟\nفقال له عمار: طبعا رافض يا رسول الله \nفقال له رسول الله ﷺ:\nلو عادوا لتعذيبك تاني وأمروك إن تشتمني فاعمل إللي يقولوا لك عليه\nونزلت في عمار آية :\n\"مَن كَفَرَ بِاللَّهِ مِن بَعْدِ إِيمَانِهِ إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُ مُطْمَئِنٌّ بِالْإِيمَانِ \"\n☆محتاجين نقف هنا وقفة\nبلال بن رباح فِضل مصمم على إيمانه وكمان كان بيغيظ الكفار، \nعمار بن ياسر مقدرش وأخذ بالرخصة،\nطيب مين الصح في الموقفين دول ،أو خلونا نقول مين الأفضل أو الأصح\nهل الأفضل إن لو الإنسان حد فتنه في دينه يثبت ويقاوم حتى لو كانت نهايته القتل زي بلال وياسر وسمية،\nولّا يستعمل التقية ويأخذ بالرخصة عشان ينجي نفسه وقلبه مطمئن بالإيمان زي عمار \nالأفضل والأَوْلى إن الإنسان يصبر ويتحمل الأذى حتى لو أدى ذلك للقتل،\nولو قُتل هيكون شهيد فهو هيبقى مأجور\nوده إللي اتفق عليه المذاهب الأربعة\nوخصوصا بقى لو كان الشخص ده عالم ممكن بسبب عدم ثباته الناس تُفتن في دينها أو دينها يتغير\nزي قصة الإمام أحمد بن حنبل\nلولا ثباته على الحق بالرغم من شدة تعذيبه لدرجة إنه كان بيفقد الوعي ،كان زمان وصل لنا الدين غلط وإن القرآن مخلوق\nوطبعا الكلام ده لا يتعارض مع النقطة إللي اتكلمنا عنها قبل كده ،\nإن العالم أو الداعية لازم يحافظ على حياته عشان يوصّل دين ربنا \nلأن في الأساس هو محافظ على حياته من أجل الدعوة، فلو تعارضت حياته مع مصلحة الدين يبقى يفدي الدين بحياته\nفالصح إن الإنسان يصبر ويثبت على دينه مهما حصل له زي ما رسول الله ﷺ قال ووصى الصحابي أبو الدرداء :\n\"أَنْ لَا تُشْرِكْ بِاللَّهِ شَيْئًا وَإِنْ قُطِّعْتَ وَحُرِّقْتَ،\n وَلَا تَتْرُكْ صَلَاةً مَكْتُوبَةً مُتَعَمِّدًا فَمَنْ تَرَكَهَا مُتَعَمِّدًا فَقَدْ بَرِئَتْ مِنْهُ الذِّمَّةُ وَلَا تَشْرَبْ الْخَمْرَ فَإِنَّهَا مِفْتَاحُ كُلِّ شَرٍّ\"\nلكن مش معنى الحديث إننا لا نأخذ بالرخصة لما نحتاجها\nوخصوصا إننا مأمورين باتباع رسول الله ﷺ وصحابته،\nفربنا قدر لعمار الموقف ده عشان الناس إللي معندهاش قدرة تحمل زي بلال بن رباح تقدر تاخد بالرخصة\n=من الصحابة إللي اتعذبوا 《صهيب  بن سِنان الرومي》\nوهو عربي الأصل ولكن وهو صغير أُخِذ أسير واتربى في بلاد الروم،\nفبقى يتكلم بلغتهم لحد ما واحد من أهل مكة اشتراه ورجع به لمكة،\nوكان صهيب ذكي جدا لدرجة إن سيده أُعجب بذكائه وحرره وشاركه في تجارة لحد ما أصبح عنده أموال كثيرة\nوكان صاحب لرسول الله ﷺ قبل البعثة،\nفلما بُعث رسول الله ﷺ أسلم صهيب مع عمار بن ياسر في نفس الساعة،\nوكان من السبعة الذين أظهروا الإسلام بين الناس وهم:\nرسول الله ﷺ، وأبو بكر وبلال وصهيب وعمار بن ياسر وسمية أمه وخَبّاب بن الأرت.\n=خبّاب بن الأَرَتْ كان من أشد الناس عذابا، كان الكفار بيولعوا الفحم أو الحجر بالنار،\n لحد ما يبقى جمر وينيّموا خبّاب على الجمر ده لدرجة ان الشحم اللي بينزل من ظهره بيطفي الجمر فكان ظهره مليان حُفر\nومع ذلك ظل ثابت على الدين ومقلش إللي الكفار عايزينه،\nده غير الجواري إللي كان الكفار بيعذبوهم،\nفكان أبو بكر الصديق بيشتري العبيد والجواري المسلمين إللي بيتعذبوا ويحررهم،\nلدرجة إن أبوه مرة بيقول له:\nإنت بتحرر الناس الضعيفة، فلو إنك حررت رجال أقوياء يقدروا يدافعوا عنك ويمنعوا عنك أذى الناس\nفقال له أبو بكر:\nأنا بعتقهم لوجه الله \nفنزلت آيات القرآن تمدحه وتذم أعداءه،\n\"فَأَنذَرْتُكُمْ نَارًا تَلَظَّىٰ ۩ لَا يَصْلَاهَا إِلَّا الْأَشْقَى\"\nالأشقى إللي هو أمية بن خلف وإللي زيه من إللي كانوا بيعذبوا المسلمين،\n\"وَسَيُجَنَّبُهَا الْأَتْقَى۩ الَّذِي يُؤْتِي مَالَهُ يَتَزكى۩ وما لِأَحَدٍ عِندَهُ مِن نِّعْمَةٍ تُجْزَىٰ۩ إِلَّا ابْتِغَاءَ وَجْهِ رَبِّهِ الْأَعْلَىٰ\"\nوالأتقى هو أبو بكر الصديق إللي سخر ماله لفداء وتحرير المستضعفين من المسلمين\nوكان من أشد الناس تعذيبا للمسلمين المستضعفين رجل من أهل مكة اسمه: 《عمر بن الخطاب》\nكان بيتطوع لتعذيب المسلمين ، \nوكان بيعذب امرأة فكان لما يسيبها يقول لها والله ما تركت تعذيبك إلا لأني زهقت\nفكانت تقول له : والله ده ربنا هو إللي صرفك عني\nالمستضعفين إللي أسلموا كان أهل مكة بيعذبوهم ، أما الأشراف زي أبو بكر ورسول الله ﷺ كان أشراف مكة هم إللي بيؤذوهم ويسخروا منهم فقط،\nمكنوش يقدروا يعذبوهم لأن لهم قبيلتهم تحميهم،\nفي يوم من الأيام ورسول الله ﷺ حاطط ردائه ونايم عليه عند الكعبة،\nجاء خبّاب بن الأرت بعد ما اشتد به وبباقي الصحابة العذاب بدأ يكلم رسول الله ﷺ ،\nقال له: يا رسول الله ألا تدعو لنا؟ ألا تستنصر لنا\nمتخيلين الألم إللي خباب فيه، طبيعي طبعا إنه يطلب من رسول الله ﷺإنه يدعو ربنا بأنه ينصرهم\nوهو دلوقتي متوقع ومستني إن رسول الله ﷺ يرفع إيده ويدعو لهم بالنصر على الناس إللي عذبت أصحابه وقتلتهم،\nلكن المفاجأة إن رسول الله ﷺ غضب\nووشه احمر من الغضب وقام قعد وقال لخباب :\nفي الناس إللي كانت قبلكم ..كانوا بيجيبوا الرجل ويحفروا له في الأرض حفرة ويحطوه فيها ،\nويجيبوا منشار ويضعوا المنشار على رأسه ويشقوه نصفين ومفكرش إنه يرجع عن دينه، \nوالله ليُتم الله أمر الإسلام حتى يسير الراكب من صنعاء إلى حضرموت لا يخاف إلا الله والذئب على غنمه ولكنكم تستعجلون\n☆صنعاء إللي كانت في اليمن في زمن رسول الله ﷺ كان بيحكمها الفرس بعد ما حكمها الحبشة إللي جاء منها أبرهة،\nفهو بيقول له إن الإسلام هينتشر لدرجة إن أملاك أقوى دولة في العالم هتبقى تحت حكم المسلمين\n◇أنا عايزاكم تحطوا نفسكم مكان خباب وهو رايح متألم وبيشكتي ورسول الله ﷺ غضب وسمّعه كلام يعتبر شديد جدا عليه في موقف زي ده،\nمش كان المفروض على الأقل إنه يواسيه بكلمتين الأول وبعدين يفهمه،\nلكن رسول الله ﷺ معملش كده\nوالأعجب بقى رد فعل خباب \nتخيلوا إنه معترضش ولا قال له بقى أنا جايلك تواسيني ولا تخفف عني بكلمتين ولا حتى تدعيلي إن ربنا يصبرني،\nتقومي تقول لي الكلام ده...هو إيه الدين ده وأنا إيه إللي يصبرني عالهم ده أصلا \nويسيبوا الدين والإلتزام بسبب شوية ابتلاءات، أو حد يقولك أصل الداعية أسلوبه وحش وكرهني في الدين،\nولكنت فظا غليظ القلب ..إيه الناس دي\nبيحصل الكلام ده في عصرنا ولّا لأ\nطيب رسول الله ﷺ كان شديد في كلامه مع خباب وكلم بغضب واحد مطحون من العذاب جاي يشتكيله،\nهل خباب ترك الدين بسبب رد فعل رسول الله ﷺ؟\nلأ...فضل ثابت ومكمل\nخلونا نشوف السبب إللي خلى رسول الله ﷺ يرد على خباب كده\nخباب لما جاء يشتكي لرسول الله ﷺ كان بيتكلم بيأس،\nوحس منه إنه فقد الأمل،\nفهو خاف على خباب أحسن ييأس من نصر ربنا ورحمته فيكون من الكافرين\n\"إِنَّهُ لَا يَيْأَسُ مِن رَّوْحِ اللَّهِ إِلَّا الْقَوْمُ الْكَافِرُونَ\"\nيعني هو مغضبش منه عشان طلب الدعاء فقط، وإلا فالدعاء أصلا سلاح المؤمن والمسلمين مطلوب منهم الدعاء من باب الأخذ بالأسباب،\nلكن المشكلة كانت في اليأس إللي كان في كلام خباب ووجهه لما شافه رسول الله ﷺ،\nفهو كان شديد معاه عشان ينبهه لحاجة أخطر من مجرد عذاب الجسد،\nالجسد كده كده هيفنى ومش هيتبقى غير الإيمان بالله ، فلازم يحافظ على الإيمان ده، \nورسول الله ﷺ رجع له الإيمان تاني من خلال كلامه :\n◇أولا :\n ذكّره بالمؤمنين إللي كانوا قبله واتعرضوا لعذاب أكبر ؛ وده لأن الناس في العادة بيهون عليها مصيبتها لما تشوف حد مُبتلى بمصائب أشد\n◇ثانيا: \nزرع جواه الأمل إن ربنا هيتم الإسلام مش بس في مكة ده حتى في ممتلكات أقوى دولة في العالم\nيعني باختصار لو وصلت لدرجة شديدة من الإيذاء متستعجلش، ربنا هيمكن لدينه أكيد\nطيب خباب المتألم المعذب إزاي تقبّل الكلام كده بكل بساطة من غير حتى ما يقول لرسول الله : يارسول الله كنت واسيني بس، الواحد ساعات محتاج حد يطبطب عليه\nمقلش كده،\nبالعكس ده رضي وثبت زي سمية وياسر إللي كان رسول الله ﷺ بيعدي عليهم ويقول لهم كلمتين: \nاصبروا وهتدخلوا الجنة\nإيه إللي يخلي المسلمين دول يستحملوا العذاب ده ويثبتوا كده\nماهو الصحابة أصلا متوجدوش بين يوم وليلة \nدول كانوا بيتربوا تربية إيمانية لمدة ثلاث سنين قبل الجهر بالدعوة\nفتخيلوا إن رسول الله ﷺ كان بيعلمهم تعظيم قدر ربنا في قلوبهم،\n♡كان بيعلمهم من هو رب العالمين، مين هو الرحمن الحكيم ، اللطيف...الخبير ..السميع ..الجبار.. القاهر فوق عباده،\nبيعلمهم إن لو ربنا قدر عليك أي ضرر فمحدش هيكشفه غيره،\n\"وَإِن يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ ۖ وَإِن يُرِدْكَ بِخَيْرٍ فَلَا رَادَّ لِفَضْلِهِ\"\n♡كان بيعلمهم يعني إيه الدار الآخرة، يعني إيه إنك لو احتسبت وصبرت على كل حاجة بتؤذيك فهي في ميزان حسناتك.\n♡كان بيعلمهم إن أكثر رجل شقاء في الدنيا لو اتغمس غمسة واحدة في الجنة هينسى شقاءه كله، أمال إللي هيعيش فيها هيبقى عامل إزاي\n♡وصف لهم الجنة فيها إيه، وصف لهم أكلهم وخدمهم ولبسهم في الجنة،\nومش هيبقى في الجنة سنة ولا سنتين ده هيبقى خالد مخلد فيها\n♡كان بيعلمهم قصص السابقين، حكى لهم قصة موسى مع فرعون،\nوإزاي ربنا نصر موسى على فرعون بعد سنين وسنين من القتل والتعذيب لبني إسرائيل 《وارجعوا للقصة واقرأوها تاني عشان تستشعروا إحساس الصحابة》\n♡كان بيزرع الأمل والثقة في نفوسهم وبيعلمهم إن إللي عايز ربنا يمكن له في الأرض لازم يصبر\n\"اسْتَعِينُوا بِاللَّهِ وَاصْبِرُوا ۖ إِنَّ الْأَرْضَ لِلَّهِ يُورِثُهَا مَن يَشَاءُ مِنْ عِبَادِهِ ۖ وَالْعَاقِبَةُ لِلْمُتَّقِينَ\"\n♡كان الصحابة بتقيم الليل فهو من أكبر الأسباب إللي بتعين على الصبر،\nوكانوا بيقرأوا القرآن وبيذكروا الله، وبيبعدوا عن المعاصي والذنوب.\nتخيلوا ثلاث سنوات متصلة رسول الله ﷺ بيعلمهم الكلام ده وعايشينه ،فأكيد طبعا لما يحصل البلاء ربنا هيثبتهم\nفرسول الله ﷺ لما قال الكلام إللي قاله لآل ياسر وقاله لخباب كأنه كان بيذكرهم  بالسنين الأولى إللي كانوا بيتعلموا فيها الإيمان، وإن هو ده إللي كنت بحكي لكم عنه فاثبتوا وانتظروا الغلبة في النهاية للإسلام\nده كان الحال بالنسبة لضعفاء المسلمين وإللي كان بيحصل معاهم من بعد الجهر بالدعوة ، واحنا دلوقتي في السنة السادسة للبعثة،\nهننتقل لرسول الله ﷺ ونشوف كان كفار قريش بيؤذوه إزاي،\nوإيه أخبار المفاوضات إللي كانت بينه وبينهم خلال الثلاث سنوات بعد الجهر بالدعوة،\nمكنش حد يقدر يؤذي رسول الله ﷺ من عامة الناس لأن رسول الله ﷺ كان في جوار أبي طالب، فكان إللي بيؤذي رسول الله ﷺ هم السادة زي ما قلنا،\nقبل ما نشوف الأذى، حصل بين رسول الله ﷺ وسادات قريش مفاوضات منها إنهم قالوا له: \nشوف يا محمد احنا هنقبل بالدين بتاعك لكن بشرط إنك تعبد إلهنا سنة ونعبد إلهك سنة \nيعني نشارك بعض في الآلهة ، لو احنا آلهتنا فيها خير يبقى إنت شاركت في الخير ده،\nولو إلهك فيه خير يبقى احنا كمان شاركنا في الخير\nفربنا أنزل : \n\"قلْ يَا أَيُّهَا الْكَافِرُونَ۩ لا أَعْبُدُ مَا تَعْبُدُونَ۩وَلا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ۩ وَلا أَنَا عَابِدٌ مَّا عَبَدتُّمْ۩وَلا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ۩لَكُمْ دِينُكُمْ وَلِيَ دِينِ\"\nربنا بيقول للمسلمين على مر العصور إن أمر العقيدة\nمفهوش جدال ولا مفاوضات، \nمع إن رسول الله ﷺ كان ممكن يتظاهر بعبادة الأصنام عشان هم يعبدوا الله ولما يعبدوه ويعرفوه ممكن يسلموا\nلكن ربنا قطع الطريق على أي مساومة في العقيدة\nمن المفاوضات إللي حصلت برده إنهم طلبوا من رسول الله ﷺ المعجزات،\nقالوا الأنبياء إللي قبلك جاءوا بمعجزات إنت مجبتش حاجة \nفقال لهم : ماهو أنا جئت لكم بكلام الله\nقالوا : لأ..احنا عايزين معجزات تانية ، عايزين آااااا....\nبكرة إن شاء الله نعرف هم عايزين إيه\n☆https://www.facebook.com/groups/710210019782034/?ref=share"}, {"n": 50, "l": "الجزء الثامن عشر | اذي المشركين لرسول الله", "u": "https://www.facebook.com/groups/710210019782034/permalink/779491546187214/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثامنة_عشرة\n#أذى_المشركين_لرسول_الله\nكنا واقفين المرة إللي فاتت عند كفار مكة لما طلبوا من رسول الله ﷺ معجزات ورسول الله ﷺ قال لهم إنه أتى لهم بكلام الله وهو أعظم معجزة،\nفقالوا: لأ ..احنا عايزين معجزات نشوفها بأعيننا\nعايزنا نؤمن بك \nفَجّر لنا من الأرض ينبوع ماء، بلادنا مفيهاش مياه فخلي الينابيع تنبع من أرض الجزيرة وتخرج فيها الحدائق والنباتات،بدل ماهي كلها صحراء كده\n\"وَقَالُوا لَن نُّؤْمِنَ لَكَ حَتَّىٰ تَفْجُرَ لَنَا مِنَ الْأَرْضِ يَنبُوعًا\"\nفقال لهم رسول الله ﷺ: أنا لم أُبعث بهذا ..أنا بشير ونذير ودي حاجة ترجع لربنا،\nفقالوا له:\nطيب بلاش دي ...عايزنا نؤمن ابعث آباءنا وأجدادنا من الموت وخلي من إللي تبعثهم 《قُصَي بن كلاب》 لأنه كان رجل صدوق،\nفهنسأله عنك لو قال إنك صادق هنصدقك احنا كمان \nفقال لهم : أنا لم أُبعث بهذا ...دي حاجة ترجع لربنا هو إللي بيبعث الموتى\nفقالوا له:\nطيب إنت بتقول إن الملائكة تأتيك صح ..خلينا نشوف الملائكة دي  عشان نصدقك\nفقال لهم: مش هتقدروا\n☆فاكرين لما رسول الله ﷺ شاف جبريل مرة واحدة بس كان خايف إزاي ومكنش مستحمل من هول خلق الملائكة\nفقالوا له : نقدر\nفقال لهم : أنا مجرد بشير ونذير ..أنا لم أبعث بهذا\nفقالوا:\nإنت محققتش لنا أي حاجة\nوعايزنا نتبعك وانت فقير...لو انت غني تستاهل إننا نتبعك، فعلى الأقل ادعي ربك إنه يجعل لك جِنان وقصور وأموال فتستحق إننا نتبعك\nفقال لهم : أمر الله مش بالغنى والفقر، ده بالإيمان\n\" أَوْ تَكُونَ لَكَ جَنَّةٌ مِّن نَّخِيلٍ وَعِنَبٍ فَتُفَجِّرَ الْأَنْهَارَ خِلَالَهَا تَفْجِيرًا\"\n\"أَوْ يَكُونَ لَكَ بَيْتٌ مِّن زُخْرُفٍ \"\nفقالوا له: إنت بتهددنا بالعذاب لو لم نؤمن بك...خلاص هات العذاب إللي انت بتقول عليه ده، وقّع علينا السماء قطعة قطعة\n\"أَوْ تُسْقِطَ السَّمَاءَ كَمَا زَعَمْتَ عَلَيْنَا كِسَفًا\"\nفقال لهم : هذا إلى الله\n\"قُلْ سُبْحَانَ رَبِّي هَلْ كُنتُ إِلَّا بَشَرًا رَّسُولًا\"\nفقالوا له: والله إنك لكذاب \nمقدرتش تحقق لنا أي حاجة من إللي احنا طلبناها، ولكن إللي بيعلمك الكلام بتاعك ده رجل من مدينة اليمامة اسمه الرحمن\n\"وَإِذَا قِيلَ لَهُمُ اسْجُدُوا لِلرَّحْمَٰنِ قَالُوا وَمَا الرَّحْمَٰنُ أَنَسْجُدُ لِمَا تَأْمُرُنَا وَزَادَهُمْ نُفُورًا\"\n☆مكنوش معترفين بأن الرحمن اسم من أسماء الله \n \nفراح قام واحد منهم وقال لرسول الله ﷺ:\nكل إللي طلبناه منك عجزت عنه، وأنا لن أؤمن بك إلا لو شفتك بتطير في الهواء لحد ما توصل للسماء وتجيب لي كتاب من السماء وألمسه بإيدي،\nوحتى لو عملت كده فأنا هعتقد إنك ساحر برده\n\"أَوْ تَرْقَىٰ فِي السَّمَاءِ وَلَن نُّؤْمِنَ لِرُقِيِّكَ حَتَّىٰ تُنَزِّلَ عَلَيْنَا كِتَابًا نَّقْرَؤُهُ\"\nفرسول الله مردش عليه...واضح من كلامه إنه معندهوش أي نية للتصديق أصلا\nقالوا والله لن نؤمن بك حتى نرى الله ونشوف الملائكة كلهم\n\" أَوْ تَأْتِيَ بِاللَّهِ وَالْمَلَائِكَةِ قَبِيلًا\"\nفرسول الله راح قايم وسابهم ومشي وهو حزين.\n☆وهنا ممكن حد يسأل هو ليه رسول الله ﷺ ما استجبش لمطالب قريش مش يمكن كانوا يؤمنوا\nهو مش الأنبياء السابقين جاءوا بالمعجزات؟\nكانت إيه النتيجة\nكلهم كذبوا... فاكرين ثمود لما طلبوا معجزة الناقة وربنا أعطاها لهم زي ما طلبوا وفي الآخر كفروا بها\n\"وَآتَيْنَا ثَمُودَ النَّاقَةَ مُبْصِرَةً فَظَلَمُوا بِهَا ۚ وَمَا نُرْسِلُ بِالْآيَاتِ إِلَّا تَخْوِيفًا\"\nموسى عليه السلام مش جاء بتسع معجزات إلى فرعون وقومه ومحدش منهم آمن\nفطلبهم للمعجزات مش عشان الإيمان ولكن جدل وخلاص،\nزي ما نيجي تقول لواحد على حكم شرعي ويقول لك فين الدليل ولما نقول له الدليل،\nيقعد يجادل ويجيب كلام من هنا وكلام من هنا،\nويقول لك لأ.. المعنى مش كده ويقعد يجادل وخلاص\nبعد ما حصل الحوار ده بين رسول الله ﷺ والمشركين ،بعث الله جبريل لرسول الله ﷺ عشان يقول له:\nيا رسول الله لو إنت عايز ...ربنا ممكن يعطيهم كل إللي طلبوه \nلكن لو كذبوا بعد ما يشوفوا المعجزات دي هيهلكوا جميعا،\nزي الأمم السابقة، أو إنك تصبر عليهم \nفرسول الله ﷺ قال : لأ...هصبر عليهم لعل الله يخرج من ذريتهم من يؤمن بالله.\nهم مفيش فيهم فائدة لكن ممكن أولادهم يبقوا مختلفين ويؤمنوا\nفربنا أنزل تعقيب على الحادثة دي بقوله:\n\"وَمَا مَنَعَنَا أَن نُّرْسِلَ بِالْآيَاتِ إِلَّا أَن كَذَّبَ بِهَا الْأَوَّلُونَ ۚ\"\nوربنا عالم الغيب بيقول لرسول الله ﷺ إنه حتى لو فتح لهم باب إلى السماء وصعدوا فيه هيقولوا سحرنا محمد\n\"وَلَوْ فَتَحْنَا عَلَيْهِم بَابًا مِّنَ السَّمَاءِ فَظَلُّوا فِيهِ يَعْرُجُونَ ۩ \nلَقَالُوا إِنَّمَا سُكِّرَتْ أَبْصَارُنَا بَلْ نَحْنُ قَوْمٌ مَّسْحُورُونَ\"\nبدأ المشركين يسخروا ويؤذوا رسول الله ﷺ والمؤمنين، اتكلمنا عن أذى المستضعفين من المؤمنين في الجزء إللي فات،\nالنهاردة هنتكلم عن أذى المشركين لرسول الله ﷺ،\n◇كانوا بيشتموه ويقولوا عنه مجنون\n\"وَقَالُوا يَا أَيُّهَا الَّذِي نُزِّلَ عَلَيْهِ الذِّكْرُ إِنَّكَ لَمَجْنُونٌ\"\n◇اتهموه بالسحر \n\"وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ ۖ وَقَالَ الْكَافِرُونَ هَٰذَا سَاحِرٌ كَذَّابٌ\"\n◇كانوا بيسخروا منه وقال أبو جهل مرة قصاد رسول الله ﷺ  بسخرية: \nيارب لو إللي محمد جاء به ده هو الحق من عندك فخلي السماء تمطر علينا حجارة أو ابعث علينا عذاب أليم\n\"وَإِذْ قَالُوا اللَّهُمَّ إِنْ كَانَ هَذَا هُوَ الْحَقَّ مِنْ عِنْدِكَ فَأَمْطِرْ عَلَيْنَا حِجَارَةً مِنَ السَّمَاءِ أَوِ ائْتِنَا بِعَذَابٍ أَلِيمٍ\"\n◇كان رسول الله ﷺ لما يقرأ القرآن عند الكعبة بيوصوا بعض إنهم يعملوا ضجة ودوشة عشان محدش يسمع القرآن ويؤثر فيه،\n\"وَقَالَ الَّذِينَ كَفَرُوا لَا تَسْمَعُوا لِهَٰذَا الْقُرْآنِ وَالْغَوْا فِيهِ لَعَلَّكُمْ تَغْلِبُونَ\"\n◇وكانوا بيقولوا إزاي يعني ربنا يبعث رسول من البشر بيأكل الطعام ويمشي في الأسواق زينا، المفروض الرسول يكون من الملائكة مش بشر\n\"وَقَالُوا مَالِ هَٰذَا الرَّسُولِ يَأْكُلُ الطَّعَامَ وَيَمْشِي فِي الْأَسْوَاقِ ۙ لَوْلَا أُنزِلَ إِلَيْهِ مَلَكٌ فَيَكُونَ مَعَهُ نَذِيرًا\"\n☆إزاي أصلا الرسول يكون من الملائكة\nالرسول وظيفته إن الناس تعمل زيه وتقلده،\nفإزاي أنا هقلد حد وهو عنده قدرات مش موجودة عندي\nيعني لما يأمرهم بالصلاة والصيام وطاعة الله هيقولوا أصل هو ملك فيقدر على كده،\nإنما احنا بشر فمش هنقدر نعمل زيه\nده الناس دلوقتي لما نقول لها رسول الله ﷺ كان بيعمل كذا ونقول لهم اعملوا زيه يقولوا ده رسول الله، فتخيلوا لو كان ملك بقى \nحتى ربنا قال لو بعثنا ملك هيكون في صورة رجل، لأن البشر ميستحملوش رؤية الملائكة، هيخافوا ويترعبوا منهم،\nفإزاي هيوصل الرسالة أصلا؟\n\"وَلَوْ جَعَلْنَاهُ مَلَكًا لَّجَعَلْنَاهُ رَجُلًا وَلَلَبَسْنَا عَلَيْهِم مَّا يَلْبِسُونَ\"\n◇كانوا بيشتموا القرآن ومن أنزله ومن جاء به،\nأول ما يسمعوا رسول الله بيقرأه بين المسلمين، فأنزل الله :\n\"ولَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا وَابْتَغِ بَيْنَ ذَٰلِكَ سَبِيلًا\"\nيعني متعليش صوتك لدرجة إن المشركين يسمعوها ولا توطي صوتك أوي لدرجة إن أصحابك ميسمعوش خلى الموضوع وسط\n◇كانوا بيدورا علة أي حاجة يعجزوا بها رسول الله ﷺ، راحوا لليهود إللي كانوا بيسكنوا المدينة وقالوا لهم:\nاحنا عندنا واحد بيقول إنه رسول وإنتم أهل الكتاب إيه رأيكم\nفقال لهم أحبار اليهود اسألوه ثلاثة أسئلة لو عرف يجاوبكم عنهم يبقى هو فعلا رسول لو مجاوبكوش يبقى كذاب\nاسألوه عن ملك طاف مشارق الأرض ومغاربها،\n إيه هي قصته، \nواسألوه عن فتية اختفوا في الزمن البعيد إيه إللي حصل معاهم، واسألوه إيه هي الروح\nفرجعوا لمكة وراحوا لرسول الله ﷺ وسألوه الأسئلة دي فقال لهم :\nهقول لكم غدا ومن الحماس نسي أن يقول إن شاء الله،\nولما جاؤوا له ثاني يوم قال لهم غدا،\nوالوحي انقطع حوالي من خمسة عشرة يوم لشهر على حسب الروايات،\nوطبعا كفار قريش قالوا إنه كاذب أهه بقالنا خمسة عشر يوم ومفيش أي حاجة\nفحزن رسول الله ﷺ لانقطاع الوحي ومن كلام أهل مكة،\nفنزل جبريل عليه السلام بسورة الكهف بيشرح فيها قصة ذو القرنين وفتية الكهف،\nواحنا اتكلمنا عنهم بالتفصيل في قصص الأنبياء ممكن ترجعوا لهم لو حابين\nالروح قال إن ميعرفش عنها حاجة لأن كل الأنبياء السابقين محدش اتكلم فيهم عن الروح، \nوهي أمرها عجيب فلو كان ربنا أوحى لرسوله معلومات عن الروح مش موجودة مع الأنبياء السابقين كانوا هيقولوا عن رسول الله ﷺ إنه كذاب،\nلأن الروح بالذات من الأمور الغيبية إللى محدش يعرف إيه هي \n\"وَيَسْأَلُونَكَ عَنِ الرُّوحِ ۖ قُلِ الرُّوحُ مِنْ أَمْرِ رَبِّي وَمَا أُوتِيتُم مِّنَ الْعِلْمِ إِلَّا قَلِيلًا\"\nكل ده كان إيذاء نفسي لكن تجرأوا عليه بإنهم يؤذوه إيذاء جسدي،\n◇لما كان رسول الله ﷺ بيصلي عند الكعبة في يوم جاءه واحد من الكفار اسمه:\n 《عقبة بن أبي مُعيْط》 وأخذ رداءه.. عبياته يعني ولفها حول رقبة رسول الله ﷺ من وراه وخنقه جدا،\n لحد ما جاء أبو بكر الصديق وخلصه منه وهو بيقول له:\nأتقتلون رجلا لمجرد إنه بيقول ربي الله\n◇في يوم من الأيام سادات مكة قاعدين عند الحِجر وكانوا حوالي سبعة، \nمنهم أبو جهل وأُبَي بن خلف فعمّالين يتكلموا عن رسول الله ﷺ ويقولوا: \nاحنا مصبرناش على أحد زي ما صبرنا على محمد ،شتم آباءنا   وشتم آلهتنا وعاب في ديننا وفرق بين جماعتنا، \nواستصغر عقولنا وطريقة تفكيرنا \nوهم عمالين يتكلموا كده لقوا رسول الله ﷺ جاي عليهم عشان يطوف حول الكعبة فكان كل ما يمر بهم يسمّعوه الكلام إللي بيقولوه،\nفرسول الله ﷺ قعد وجهه يتغير من كلامهم،\nزي كده لما واحد يبقى معدي على ناس ويقعدوا يتريقوا عليه\nفي الرايحة وفي الجاية فيتحرق دمه\nفعدى عليهم أول مرة فقعدوا يتكلموا ويشتموه ووجهه يتغير،\nوالمرة الثانية برده وهو ساكت وصابر،\nولما عملوا كده في المرة الثالثة وقف وبص لهم وقال لهم:\nعارفين يا معشر قريش...والذي نفس محمد بيده إنما جئتكم بالذبح\nالسبعة إللي كانوا قاعدين تنحوا واتصدموا من الكلمة \nأصل إللي قال الكلام 《الصادق الأمين》\nهم أه بيكذبوه بس هم عارفين من جواهم إنه صادق وإنه على حق، فلما يقول لهم إنما جئتكم بالذبح يبقى هو فعلا جاءهم بالذبح\nفراحوا كلهم قايمين له وقعدوا يستسمحوه، ويقولوا له الكلام اللين وقالوا له:\nانصرف يا أبا القاسم، انصرف راشدا والله ما كنت جهولا\nفلما مشي رسول الله ﷺ قالوا لبعض:\nبقى احنا عمالين نتكلم ومتفقين ننتقم منه ولما بس هو هددنا بشوية كلام خفتم منه\nلما ييجي بكرة هنتصرف معاه\nوأول ما جاء رسول الله ﷺ تاني يوم راحوا قايمين عليه مرة واحدة وحاوطوه وواحد منهم مسك رسول الله ﷺ من ردائه من عند رقبته كده، \nماسك في خناقه يعني، ووقعدوا يقولوا إنت إللي بتشتم آلهتنا، إنت إللي بتقول كذا وكذا\nفقال لهم رسول الله ﷺ: نعم أنا إللي بقول كده\nفشاف الموقف أبو بكر الصديق وراح مخلص رسول الله ﷺ  منهم وهو بيبكي وبيقول:\n \"أتقتلون رجلا أن يقول ربي الله\" \n☆طبعا حديث إنما جئتكم بالذبح ده في بعض الناس أخذته وقعدت تبرر به قتل الأبرياء سواء من المسلمين أو المُعاهدين، ده غير الناس إللي مصدقت تطعن في رسول الله ﷺ،\nده غير الشك إللي ممكن يدخل في قلوب المسلمين،\nإزاي ربنا بيقول وما أرسلناك إلا رحمة للعالمين، ومنين رسول الله ﷺ بيقول إنما جئتكم بالذبح\n◇أولا:\nالحديث ده خاص بفئة معينة وهم كفار قريش إللي آذوا رسول الله ﷺ وعذبوا الصحابة وقتلوا منهم وأي حد يكون على شاكلتهم ،\nفالكلام كان موجه بالذات للسبعة إللي كانوا قاعدين في الحِجر ،\nوالسبعة دول إللي كانوا مصرّين على الكفر، وكانوا بيعذبوا المسلمين أشد العذاب،\nوقتلوا سمية وياسر وعذبوا عمار وبلال وصهيب وكل المستضعفين، وكانوا عايزين يقتلوا رسول الله ﷺ\nوفي مرة ثانية كانوا قاعدين عند الكعبة وقعدوا يحلفوا بآلهتهم إنهم أول ما يشوفوا محمد هيقوموا عليه قومة رجل واحد فيقتلوه،\nفسمعتهم فاطمة بنت رسول الله ﷺ وراحت لأبوها تبكي وتحكي له على إللي سمعته،\nفقام رسول الله ﷺ وتوضأ وراح لحد عندهم عند الكعبة،\nفمحدش قدر حتى يرفع عينه في عين رسول الله ﷺ ولا حد قدر يقوم يقوم له،\nومسك رسول الله ﷺ شوية تراب ورماهم بها وقال لهم: \nشاهت الوجوه يعني قبُحَت الوجوه ، فمحدش أصابه من التراب ده إلا وقُتل يوم بدر كافرا زي ما هنشوف،\nودي معجزة لرسول الله ﷺ، إن الوعيد بتاعه تحقق\nفعشان بس الناس إللي بتاخد الحديث وتطلع الكلام من سياقه وتقول إن الإسلام أو رسول الله ﷺ جاء بالذبح،\nويبقى حجة لهم لقتل ناس أبرياء لمجرد إنهم كفار فقط غير محاربين ولم يتبعوا دين الإسلام،\nأو عشان يطعنوا في رسول الله ﷺ\nطبعا الكفار المحاربين إللي بيقتلوا المستضعفين من المسلمين لهم وضع تاني،\nهنعرفه بعدين إن شاء الله من خلال الأحداث\n◇ثانيا:\nرسول الله ﷺ جاء رحمة للعالمين أيوة، ولما قيل له يا رسول الله ،ادع على المشركين!\nقال : إني لم أُبْعث لعّانا وإنما بُعثت رحمة\nوزي ما شفنا إنه رفض إن ربنا يرسل المعجزات عشان أهل مكة ميكذبوش فربنا يهلكهم\nفرسول الله ﷺ لا ينطق عن الهوى فزي ماهو رحمة للعالمين، فهو بيتوعد أشد الناس كفرا وتعذيبا للمسلمين ،\nولسه هنشوف مواقف لهم عملوا إيه مع رسول الله ﷺ ومع المسلمين\nومكنش الوضع شهر ولا شهرين ولا سنة ولا سنتين دول قعدوا أكثر من عشر سنين\n◇فالمختصر المفيد إن حديث إنما جئتكم بالذبح جا لناس معينة في ظرف معين سواء في عهد رسول الله ﷺ مش إن الإسلام جاء بالذبح على الإطلاق\nمن الناس إللي أذوا رسول الله ﷺ جدا كان أبو جهل، \nفي مرة كان راح عند الكعبة وسأل الناس الموجودين هل محمد بييجي يسجد عند الكعبة يصلي\nفالناس قالت له: نعم\nفقال : واللات والعزى لو شفته بيعمل كده لأدوس على رقبته أو أُعَفّر وجهه في التراب\nفجاء رسول الله ﷺ عشان يصلي عند الكعبة ، فراح أبو جهل قايم عشان يدوس على رقبته، وفجأة لقوا أبو جهل بيرجع لورا بسرعة،\nوحاطط إيده على وشه، كأنه بيحمي وشه من حاجة \nفالناس سألته: مالك \nقال لهم : بيني وبينه خندق من نار وأجنحة \nفقال رسول الله ﷺ: لو كان قرّب مني لاختطفته الملائكة عضو عضو\nفأنزل الله فيه:\n\"كَلَّا إِنَّ الْإِنْسَانَ لَيَطْغَى ۩ أَنْ رَآهُ اسْتَغْنَى ۩\n إِنَّ إِلَى رَبِّكَ الرُّجْعَى ۩ أَرَأَيْتَ الَّذِي يَنْهَى ۩ عَبْدًا إِذَا صَلَّى ۩ أَرَأَيْتَ إِنْ كَانَ عَلَى الْهُدَى ۩\n أَوْ أَمَرَ بِالتَّقْوَى ۩ أَرَأَيْتَ إِنْ كَذَّبَ وَتَوَلَّى ۩ أَلَمْ يَعْلَمْ بِأَنَّ اللَّهَ يَرَى ۩\n كَلَّا لَئِنْ لَمْ يَنْتَهِ لَنَسْفَعًا بِالنَّاصِيَةِ ۩ نَاصِيَةٍ كَاذِبَةٍ خَاطِئَةٍ ۩ فَلْيَدْعُ نَادِيَهُ ۩ سَنَدْعُ الزَّبَانِيَةَ ۩ كَلَّا لَا تُطِعْهُ وَاسْجُدْ وَاقْتَرِبْ\"\n☆شوفوا سبحان الله \nيعني أبو جهل شاف معجزة قصاده أهه ومع ذلك لم يؤمن\n\"فَإِنَّهَا لَا تَعْمَى الْأَبْصَارُ وَلَٰكِن تَعْمَى الْقُلُوبُ الَّتِي فِي الصُّدُورِ\"\nومن الأذى إللي تعرض له رسول الله ﷺ بيحكيه الصحابي عبد الله بن مسعود:\nبيقول إنه مرة كان يصلي عند البيت ، وأبو جهل ومعاه أصحاب له قاعدين، فقالوا لبعض: \nمين يروح يجيب أمعاء البعير بتاع آل فلان إللي ذبحوه ويضعه على ظهر محمد وهو ساجد\nفقام أشقاهم عقبة بن أبي معيط وجاب الأمعاء وأول ما رسول الله ﷺ سجد راح حاطه على ظهره بين كتفيه،\nوقعدوا يضحكوا على رسول الله ﷺ لدرجة إنهم قعدوا يتمايلوا على بعض من الضحك\nبيقول عبد الله بن مسعود إن رسول الله ﷺ ظل ساجد لحد ما جاءت فاطمة وشالت الأمعاء من على ظهره وأنا مكنتش قادر أعمل حاجة\nفقام رسول الله ﷺ وقال : اللهم عليك بقريش ..اللهم عليك بقريش..اللهم عليك بقريش\n☆طبعا الدعاء هنا كان على الناس إللي عملت كده مش على كل قريش\n◇لو انتبهتم إن كل مرة بيؤذوا رسول الله ﷺ كان بيبقى وهو بيصلي،\nيعني هو بيطيع ربنا ولم يؤذي أحد ومع ذلك كان رسول الله ﷺ بيتعرض للأذى وساعات القتل،\nومفكرش مرة إنه يقول خلاص أنا مش هروح أصلي عند المجالس بتاعتهم تاني،\nوده يعلمنا إننا نثبت على الحق مهما كان الأذى، ونستمر في الدعوة مهما كانت الناس مش عاجبها\nويعلمنا كمان إن مش معنى إن ربنا بيسلط بعض الكفار والظلمة على المؤمنين فده لِهوَان المؤمنين عليه سبحانه، \nولا لأنه غير قادر إنه يمنع الأذى عنهم ولكنه سبحانه له حكم وتدابير لا يعلمها غيره\nوده يخلينا نسأل سؤالين مهمين\n¤ليه ربنا يبتلي المؤمنين وعلى رأسهم رسوله وأحب الخلق إليه كده ويسلط عليهم الكفار \n¤والسؤال الثاني ليه المسلمين ورسول الله ﷺ صبروا ومردوش على الكفار وحملوا السلاح ودافعوا عن أنفسهم\nهنعرف الإجابة إن شاء الله الجزء الجاي، وهنشوف بدايات الفرج للمسلمين بعد ثلاث سنوات من القهر والتعذيب\n☆"}]);
